/// Number of emergency passes at >=95% pressure where reclaim excluded at least one tool arc
/// because removing it would leave a signed, reasoning-only assistant message. Operations uses
/// this count to distinguish low reclaim caused by that safety rule from a selector regression.
pub fn emergency_reasoning_exclusion_count() -> u64 {
    EMERGENCY_REASONING_EXCLUSIONS.load(Ordering::Relaxed)
}

#[cfg(test)]
fn reset_emergency_reasoning_exclusion_count() {
    EMERGENCY_REASONING_EXCLUSIONS.store(0, Ordering::Relaxed);
}

// Real 5k-message sessions retain 24-55 MiB of canonical output plus typed CK trees. A 64 MiB
// ceiling refused those single-session snapshots, turning every warm pass into a full re-encode.
pub(crate) const SERIALIZED_OUTPUT_CACHE_BUDGET_BYTES: usize = 256 * 1024 * 1024;
const TAG_BASELINE_CACHE_BUDGET_BYTES: usize = 64 * 1024 * 1024;
const TAG_MINT_FRONTIER_CACHE_BUDGET_BYTES: usize = 64 * 1024 * 1024;

/// One served CK message plus the canonical bytes used by the module response writer.
/// The typed value stays behind an `Arc`, so a cache hit does not clone large tool output trees.
#[derive(Debug, Clone)]
pub struct ServedMessage {
    message: Arc<CkWireMessage>,
    canonical_bytes: Arc<[u8]>,
    canonical_hash: [u8; 32],
    output_identity: Arc<str>,
    block_fingerprints: Arc<[(String, usize)]>,
    retained_bytes: usize,
}

fn canonical_message_bytes(message: &CkWireMessage) -> Vec<u8> {
    message
        .to_canonical_json_vec()
        .expect("CK wire messages must always serialize")
}

#[cfg(test)]
fn canonical_message_bytes_reference(message: &CkWireMessage) -> Vec<u8> {
    let value = serde_json::to_value(message)
        .expect("CK wire messages must always have a JSON representation");
    serde_json::to_vec(&value).expect("CK wire message values must always serialize")
}

impl ServedMessage {
    fn from_message(message: CkWireMessage) -> Self {
        Self::from_message_reusing(message, None)
    }

    /// Build a served message, reusing each projected block's retained content hash when
    /// the served wire is still identical to that projection block.
    ///
    /// Divergence fingerprints hash the same serialized `CkWireBlock` basis the
    /// projection already hashed into `FlatBlock.content_hash`. Overlaid, reduced, or
    /// otherwise rewritten blocks fall back to a fresh serialize+hash.
    fn from_message_reusing(
        message: CkWireMessage,
        projected_blocks: Option<&[&FlatBlock]>,
    ) -> Self {
        let canonical_bytes = canonical_message_bytes(&message);
        let block_fingerprints = message
            .content
            .iter()
            .enumerate()
            .map(|(served_index, block)| {
                let projected = projected_blocks.and_then(|blocks| {
                    blocks
                        .iter()
                        .find(|flat| flat.block_index == served_index)
                        .copied()
                        .or_else(|| {
                            // Full-drop paths compact content indexes; match by wire value.
                            blocks
                                .iter()
                                .copied()
                                .find(|flat| flat.wire.as_ref() == block)
                        })
                });
                if let Some(fp) = ck_wire::fingerprint_from_projected_wire(block, projected) {
                    return fp;
                }
                let serialized = serde_json::to_string(block)
                    .expect("CK wire blocks must always have a JSON representation");
                (ck_wire::fingerprint(&serialized), serialized.len())
            })
            .collect::<Vec<_>>();
        let canonical_digest = Sha256::digest(&canonical_bytes);
        let output_identity = format!("{canonical_digest:x}");
        let canonical_hash: [u8; 32] = canonical_digest.into();
        let message = Arc::new(message);
        let canonical_bytes: Arc<[u8]> = Arc::from(canonical_bytes);
        let output_identity: Arc<str> = Arc::from(output_identity);
        let block_fingerprints: Arc<[(String, usize)]> = Arc::from(block_fingerprints);
        let retained_bytes = served_message_retained_bytes(
            &message,
            &canonical_bytes,
            &output_identity,
            &block_fingerprints,
        );
        Self {
            message,
            canonical_bytes,
            canonical_hash,
            output_identity,
            block_fingerprints,
            retained_bytes,
        }
    }

    fn with_output_identity(mut self, identity: &str) -> Self {
        self.retained_bytes = self
            .retained_bytes
            .saturating_sub(self.output_identity.len())
            .saturating_add(identity.len());
        self.output_identity = Arc::from(identity);
        self
    }

    pub(crate) fn native_identity_basis(&self) -> (&str, &[u8; 32]) {
        (&self.output_identity, &self.canonical_hash)
    }

    pub fn into_message(self) -> CkWireMessage {
        Arc::try_unwrap(self.message).unwrap_or_else(|message| (*message).clone())
    }

    pub(crate) fn canonical_bytes(&self) -> &[u8] {
        &self.canonical_bytes
    }

    fn retained_bytes(&self) -> usize {
        self.retained_bytes
    }
}

fn served_message_retained_bytes(
    message: &Arc<CkWireMessage>,
    canonical_bytes: &Arc<[u8]>,
    output_identity: &Arc<str>,
    block_fingerprints: &Arc<[(String, usize)]>,
) -> usize {
    use crate::retained_size::{ck_wire_message_retained_bytes, ARC_ALLOCATION_OVERHEAD_BYTES};
    use std::mem::size_of;

    ARC_ALLOCATION_OVERHEAD_BYTES
        .saturating_add(ck_wire_message_retained_bytes(message))
        .saturating_add(ARC_ALLOCATION_OVERHEAD_BYTES)
        .saturating_add(canonical_bytes.len())
        .saturating_add(ARC_ALLOCATION_OVERHEAD_BYTES)
        .saturating_add(output_identity.len())
        .saturating_add(ARC_ALLOCATION_OVERHEAD_BYTES)
        .saturating_add(
            block_fingerprints
                .len()
                .saturating_mul(size_of::<(String, usize)>()),
        )
        .saturating_add(
            block_fingerprints
                .iter()
                .map(|(fingerprint, _)| fingerprint.capacity())
                .sum::<usize>(),
        )
}

impl Deref for ServedMessage {
    type Target = CkWireMessage;

    fn deref(&self) -> &Self::Target {
        &self.message
    }
}

impl PartialEq for ServedMessage {
    fn eq(&self, other: &Self) -> bool {
        self.message == other.message
    }
}

impl PartialEq<CkWireMessage> for ServedMessage {
    fn eq(&self, other: &CkWireMessage) -> bool {
        self.message.as_ref() == other
    }
}

impl Serialize for ServedMessage {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        self.message.serialize(serializer)
    }
}

impl<'de> Deserialize<'de> for ServedMessage {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        CkWireMessage::deserialize(deserializer).map(Self::from_message)
    }
}

#[derive(Debug, Clone)]
struct SerializedOutputCacheEntry {
    identity: String,
    served: Option<ServedMessage>,
}

#[derive(Debug, Clone, Default)]
struct SerializedOutputCacheSnapshot {
    entries: HashMap<String, SerializedOutputCacheEntry>,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub(crate) struct SerializedOutputCacheStats {
    pub reused_items: usize,
    pub serialized_items: usize,
}

#[derive(Debug)]
struct SerializedOutputSession {
    revert_epoch: u64,
    retained_bytes: usize,
    entries: HashMap<String, SerializedOutputCacheEntry>,
    #[cfg_attr(not(test), allow(dead_code))]
    stats: SerializedOutputCacheStats,
}

#[derive(Debug)]
pub(crate) struct SerializedOutputCache {
    sessions: HashMap<String, SerializedOutputSession>,
    lru: VecDeque<String>,
    retained_bytes: usize,
    max_retained_bytes: usize,
}

impl Default for SerializedOutputCache {
    fn default() -> Self {
        Self::new(SERIALIZED_OUTPUT_CACHE_BUDGET_BYTES)
    }
}

impl SerializedOutputCache {
    fn new(max_retained_bytes: usize) -> Self {
        Self {
            sessions: HashMap::new(),
            lru: VecDeque::new(),
            retained_bytes: 0,
            max_retained_bytes,
        }
    }

    fn entries_retained_bytes(
        session_id: &str,
        entries: &HashMap<String, SerializedOutputCacheEntry>,
    ) -> usize {
        use crate::retained_size::{cloned_string_retained_bytes, hash_map_allocation_bytes};
        use std::mem::size_of;

        hash_map_allocation_bytes(entries)
            .saturating_add(
                entries
                    .iter()
                    .map(|(key, entry)| {
                        key.capacity()
                            .saturating_add(entry.identity.capacity())
                            .saturating_add(
                                entry
                                    .served
                                    .as_ref()
                                    .map_or(0, ServedMessage::retained_bytes),
                            )
                    })
                    .sum::<usize>(),
            )
            // Include the outer cache bucket/control slack and its two independently allocated
            // session keys. The three-word allowance models hash-table control and load slack.
            .saturating_add(size_of::<SerializedOutputSession>())
            .saturating_add(size_of::<usize>() * 3)
            .saturating_add(cloned_string_retained_bytes(session_id).saturating_mul(2))
    }

    pub(crate) fn metrics(&self) -> (usize, usize) {
        let entry_count = self
            .sessions
            .values()
            .map(|session| session.entries.len())
            .sum();
        (self.retained_bytes, entry_count)
    }

    pub(crate) fn remove(&mut self, session_id: &str) {
        if let Some(session) = self.sessions.remove(session_id) {
            self.retained_bytes = self.retained_bytes.saturating_sub(session.retained_bytes);
        }
        self.lru.retain(|candidate| candidate != session_id);
    }

    fn snapshot(&mut self, session_id: &str, revert_epoch: u64) -> SerializedOutputCacheSnapshot {
        if self
            .sessions
            .get(session_id)
            .is_some_and(|session| session.revert_epoch != revert_epoch)
        {
            self.remove(session_id);
        }
        let entries = self
            .sessions
            .get(session_id)
            .map(|session| session.entries.clone())
            .unwrap_or_default();
        if !entries.is_empty() {
            self.lru.retain(|candidate| candidate != session_id);
            self.lru.push_back(session_id.to_string());
        }
        SerializedOutputCacheSnapshot { entries }
    }

    fn replace(
        &mut self,
        session_id: &str,
        revert_epoch: u64,
        entries: HashMap<String, SerializedOutputCacheEntry>,
        stats: SerializedOutputCacheStats,
    ) {
        self.remove(session_id);
        let retained_bytes = Self::entries_retained_bytes(session_id, &entries);
        if retained_bytes > self.max_retained_bytes {
            return;
        }
        self.retained_bytes = self.retained_bytes.saturating_add(retained_bytes);
        self.sessions.insert(
            session_id.to_string(),
            SerializedOutputSession {
                revert_epoch,
                retained_bytes,
                entries,
                stats,
            },
        );
        self.lru.push_back(session_id.to_string());
        while self.retained_bytes > self.max_retained_bytes {
            let Some(oldest) = self.lru.pop_front() else {
                break;
            };
            if let Some(session) = self.sessions.remove(&oldest) {
                self.retained_bytes = self.retained_bytes.saturating_sub(session.retained_bytes);
            }
        }
    }

    #[cfg(test)]
    fn stats(&self, session_id: &str) -> SerializedOutputCacheStats {
        self.sessions
            .get(session_id)
            .map(|session| session.stats)
            .unwrap_or_default()
    }
}

fn log_pending_m1_delta(session_id: &str, now_ms: i64, pending_since_ms: Option<i64>) {
    let age_ms = now_ms.saturating_sub(pending_since_ms.unwrap_or(now_ms).max(0));
    let bucket = M1_PENDING_LOG_THRESHOLDS_MS
        .iter()
        .enumerate()
        .filter(|(_, threshold)| age_ms >= **threshold)
        .map(|(index, _)| index + 1)
        .next_back()
        .unwrap_or(0);
    if bucket == 0 {
        return;
    }
    let buckets = M1_PENDING_LOG_BUCKETS.get_or_init(|| Mutex::new(HashMap::new()));
    let mut buckets = buckets.lock().expect("m1 pending log mutex");
    if buckets.get(session_id).copied().unwrap_or(0) < bucket {
        buckets.insert(session_id.to_string(), bucket);
        eprintln!("mc-module: pending_m1_delta=true age_ms={age_ms} session={session_id}");
    }
}

