/// Render the one-line, greppable timing record emitted after the response splice.
///
/// Session ids are made whitespace-safe because each field is parsed as one `key=value` token.
pub fn format_pass_timing_line(
    session_id: &str,
    timings: &TransformTimings,
    response_encode_ms: f64,
) -> String {
    let session = if session_id.is_empty() {
        "-".to_string()
    } else {
        session_id
            .chars()
            .map(|character| {
                if character.is_whitespace() {
                    '_'
                } else {
                    character
                }
            })
            .collect()
    };
    format!(
        "mc-pass-timing session={session} total={:.1} handler_total={:.1} request_decode={:.1} handler_prepare={:.1} transform_execute={:.1} handler_followup={:.1} request_observed_to_handler={:.1} \
         delta_expand={:.1} side_channel_drain={:.1} trace_received={:.1} projection_cache_lookup={:.1} projection_cache_store={:.1} \
         native_attach={:.1} trace_complete={:.1} response_observation={:.1} retained_size={:.1} snapshot_store={:.1} projection={:.1} \
         projection_reused_messages={} projection_projected_messages={} store_cache_state={:.1} store_tags={:.1} store_temporal={:.1} \
         store_user_hints={:.1} store_channel1={:.1} store_overlay_frontier={:.1} \
         store_notes={:.1} store_memories={:.1} pending_drops={:.1} coverage_resolve={:.1} \
         identity_enforce={:.1} state_clone={:.1} ingress_meta={:.1} user_hint={:.1} \
         planning={:.1} state_evolution={:.1} finalize={:.1} \
         tag_overlay={:.1} unit_mint={:.1} temporal={:.1} caveman={:.1} \
         tag_mint_candidates={} tag_mint_new={} tag_mint_tokenized_bytes={} \
         decide={:.1} seed_or_sync={:.1} compose_m0m1={:.1} selection={:.1} \
         transition_detection={:.3} emergency_reasoning_exclusions={} todo={:.1} \
         blocks_by_mid={:.1} build_frozen_unit_index={:.1} full_drop_tool_ids={:.1} \
         build_output={:.1} build_identity={:.1} build_identity_max={:.1} build_frozen_unit_scan={:.1} \
         build_cache_lookup={:.1} build_serialize_misses={:.1} build_serialized_messages={} build_tail_loop={:.1} \
           divergence={:.1} store_commit={:.1} trigger_ms={:.1} trigger_boundary_build={:.1} trigger_eval={:.1} \
             trigger_cache_store={:.1} trigger_token_cache_hits={} trigger_tokenized_blocks={} \
             post_attach_ms={:.1} native_cache_reused_messages={} native_cache_encoded_messages={} \
            native_cache_refused_store={} native_cache_degraded_store={} native_cache_evicted={} \
             response_encode={response_encode_ms:.1} response_meta_encode={:.1} response_size_account={:.1} response_splice={:.1} \
             frozen_units={} tail_units_matched={} \
           projection_blocks={} tail_messages_emitted={} build_identity_messages={} \
           cache_hits={} cache_misses={} cache_dirty_skips={}",
        timings.total,
        timings.handler_total,
        timings.request_decode,
        timings.handler_prepare,
        timings.transform_execute,
        timings.handler_followup,
        timings.request_observed_to_handler,
        timings.delta_expand,
        timings.side_channel_drain,
        timings.trace_received,
        timings.projection_cache_lookup,
        timings.projection_cache_store,
        timings.native_attach,
        timings.trace_complete,
        timings.response_observation,
        timings.retained_size,
        timings.snapshot_store,
        timings.projection,
        timings.projection_reused_messages,
        timings.projection_projected_messages,
        timings.store_cache_state,
        timings.store_tags,
        timings.store_temporal,
        timings.store_user_hints,
        timings.store_channel1,
        timings.store_overlay_frontier,
        timings.store_notes,
        timings.store_memories,
        timings.pending_drops,
        timings.coverage_resolve,
        timings.identity_enforce,
        timings.state_clone,
        timings.ingress_meta,
        timings.user_hint,
        timings.planning,
        timings.state_evolution,
        timings.finalize,
        timings.tag_overlay,
        timings.unit_mint,
        timings.temporal,
        timings.caveman,
        timings.tag_mint_candidates,
        timings.tag_mint_new,
        timings.tag_mint_tokenized_bytes,
        timings.decide,
        timings.seed_or_sync,
        timings.compose_m0m1,
        timings.selection,
        timings.transition_detection,
        timings.emergency_reasoning_exclusions,
        timings.todo,
        timings.blocks_by_mid,
        timings.build_frozen_unit_index,
        timings.full_drop_tool_ids,
        timings.build_output,
        timings.build_identity,
        timings.build_identity_max,
        timings.build_frozen_unit_scan,
        timings.build_cache_lookup,
        timings.build_serialize_misses,
        timings.build_serialized_messages,
        timings.build_tail_loop,
        timings.divergence,
        timings.store_commit,
        timings.trigger_ms,
        timings.trigger_boundary_build,
        timings.trigger_eval,
        timings.trigger_cache_store,
        timings.trigger_token_cache_hits,
        timings.trigger_tokenized_blocks,
        timings.post_attach,
        timings.native_cache_reused_messages,
        timings.native_cache_encoded_messages,
        timings.native_cache_refused_store,
        timings.native_cache_degraded_store,
        timings.native_cache_evicted,
        timings.response_meta_encode,
        timings.response_size_account,
        timings.response_splice,
        timings.frozen_units,
        timings.tail_units_matched,
        timings.projection_blocks,
        timings.tail_messages_emitted,
        timings.build_identity_messages,
        timings.cache_hits,
        timings.cache_misses,
        timings.cache_dirty_skips,
    )
}

/// A transform pass result. Diagnostics remain alongside the CK array, but the response
/// messages themselves are bare CK messages: no request-only `mid` or `ordinal` sidecar.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct NativeMessagesDelta {
    pub after: String,
    pub replace_from: usize,
    pub messages: Vec<Arc<Value>>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct TransformResponse {
    /// Native vectors protected while newest remain unchanged until the next priced pass.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub native_reasoning_keep_mids: Vec<String>,
    pub status: TransformStatus,
    pub served_from: ServedFrom,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub full_array_fingerprint: Option<String>,
    pub action: String,
    /// The classifier decision, duplicated from `action` for telemetry consumers that do not
    /// need to interpret the legacy action field.
    #[serde(default)]
    pub decision: String,
    /// Canonical execute/defer class shared with TypeScript transform telemetry.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub scheduler_decision: Option<String>,
    /// Canonical TypeScript refusal reason when the scheduler class is defer.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub scheduler_defer_reason: Option<String>,
    /// The classifier's raw cause for a HARD/SOFT decision. Unknown future causes are retained.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub materialize_reason: Option<String>,
    /// First position where the newly served block sequence differs from the previous sequence,
    /// excluding blocks added only at the end.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub first_divergence: Option<FirstDivergence>,
    /// Optional diagnostic timings. Omitted only by compatibility constructors and on old
    /// responses; normal module transform passes include this object.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub timings: Option<TransformTimings>,
    pub boundary_id: String,
    pub reconcile_pending: bool,
    pub version: u64,
    pub row_version: u64,
    pub surface_state: SurfaceState,
    pub committed: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub coverage_ordinal: Option<u64>,
    /// Memory IDs currently shown in the module's memory view. The host copies this list to
    /// filter search results, using the module manifest rather than its TypeScript render cache.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub rendered_memory_ids: Option<Vec<i64>>,
    /// Exact composed edge id consumed by observed durable state. Omitted on ordinary,
    /// subagent, defer-only protocol-error, and pending-build-skew responses.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub lineage_switch_consumed_id: Option<u64>,
    /// Outcome of the resolved descent edge ("descended", "replay", or a
    /// terminal refusal). Present exactly when an edge was resolved this
    /// pass; lets the sender distinguish inheritance from refusal without
    /// reading this module's store.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub lineage_descent_disposition: Option<String>,
    /// TTL the consumer must apply to every cache marker it places on this
    /// response. Absent = inherit whatever the harness authored (today's
    /// behaviour), so old/new module+gateway mixes are no-ops in both directions.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub cache_ttl: Option<String>,
    /// Prior lineage tail used as the provisional ordinal base for native adapters.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub ordinal_continuation_base: Option<u64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub historian: Option<HistorianDiagnostics>,
    /// The actual output messages for this pass: synthetic m0 and m1 messages followed
    /// by the tail messages, all expressed as bare CK messages. `None` (field ABSENT on
    /// the wire) on a `need_full_sync` response: the consumer discriminates structurally
    /// on array presence, and an empty array would be a third ambiguous state between
    /// "transformed to nothing" and "re-send required". Every `ok` response carries
    /// `Some`, even when legitimately empty.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub ck_messages: Option<Vec<ServedMessage>>,
    /// OpenCode message-with-parts output, present only when the request opted into native
    /// serving and selected the `opencode-aisdk` serializer profile.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub native_messages: Option<Vec<Arc<Value>>>,
    /// Replacement suffix over the previous acknowledged native output. This keeps a warm response
    /// proportional to the changed tail while preserving the full-array field as the fallback.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub native_messages_delta: Option<NativeMessagesDelta>,
    /// Host-delivery instructions are additive and profile-gated. The module does not
    /// persist delivery because the host owns the channel-2 lease and deduplication.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub host_directives: Option<HostDirectives>,
    /// Claude Code gateway instruction. It is response metadata and never enters `ck_messages`.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub channel2_directive: Option<Channel2Directive>,
    /// Delivery ledger rows whose note bytes were included in this bust. The host sends
    /// the existing transform.ack/nack after applying and validating the response.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub note_deliveries: Option<Vec<NoteDelivery>>,
}

impl TransformResponse {
    /// The output array of an `ok`/passthrough response; empty for `need_full_sync`
    /// (whose wire form omits the field entirely).
    pub fn messages(&self) -> &[ServedMessage] {
        self.ck_messages.as_deref().unwrap_or(&[])
    }

    pub fn need_full_sync(full_array_fingerprint: Option<String>) -> Self {
        Self {
            native_reasoning_keep_mids: Vec::new(),
            status: TransformStatus::NeedFullSync,
            served_from: ServedFrom::Transform,
            full_array_fingerprint,
            action: "NEED_FULL_SYNC".to_string(),
            decision: "NEED_FULL_SYNC".to_string(),
            scheduler_decision: None,
            scheduler_defer_reason: None,
            materialize_reason: None,
            first_divergence: None,
            timings: None,
            boundary_id: String::new(),
            reconcile_pending: false,
            version: 0,
            row_version: 0,
            surface_state: SurfaceState::Inactive,
            committed: false,
            coverage_ordinal: None,
            rendered_memory_ids: None,
            lineage_switch_consumed_id: None,
            lineage_descent_disposition: None,
            cache_ttl: None,
            ordinal_continuation_base: None,
            historian: None,
            ck_messages: None,
            native_messages: None,
            native_messages_delta: None,
            host_directives: None,
            channel2_directive: None,
            note_deliveries: None,
        }
    }

    pub fn passthrough(
        ck_messages: Vec<CkWireMessage>,
        full_array_fingerprint: Option<String>,
    ) -> Self {
        Self {
            native_reasoning_keep_mids: Vec::new(),
            status: TransformStatus::Ok,
            served_from: ServedFrom::Transform,
            full_array_fingerprint,
            action: "PASSTHROUGH".to_string(),
            decision: "PASSTHROUGH".to_string(),
            scheduler_decision: None,
            scheduler_defer_reason: None,
            materialize_reason: None,
            first_divergence: None,
            timings: None,
            boundary_id: String::new(),
            reconcile_pending: false,
            version: 0,
            row_version: 0,
            surface_state: SurfaceState::Inactive,
            committed: false,
            coverage_ordinal: None,
            rendered_memory_ids: None,
            lineage_switch_consumed_id: None,
            lineage_descent_disposition: None,
            cache_ttl: None,
            ordinal_continuation_base: None,
            historian: None,
            ck_messages: Some(
                ck_messages
                    .into_iter()
                    .map(ServedMessage::from_message)
                    .collect(),
            ),
            native_messages: None,
            native_messages_delta: None,
            host_directives: None,
            channel2_directive: None,
            note_deliveries: None,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct HistorianDiagnostics {
    pub fired: bool,
    pub reason: Option<String>,
    /// Existing transform consumers still read this coarse Rust discriminant; newer
    /// consumers use the additional structured fields below.
    pub no_fire: Option<String>,
    /// Structured diagnostic detail retaining the raw Rust cause and its TypeScript-aligned class.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub no_fire_detail: Option<String>,
    /// Canonical TypeScript no-fire vocabulary for adapter logs and incident grep parity.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub canonical_cause: Option<String>,
    pub state: String,
    /// Tail-size progress numbers from the trigger's boundary resolution, absent when the
    /// pass never reached boundary resolution (busy, load failure, no messages). Purely
    /// observational: lets a rig drive see eligible content approach the fire bar per pass.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub progress: Option<HistorianTriggerProgress>,
    /// Detail of the most recent failed firing, from durable state. Present until a later
    /// firing establishes its producer run; supervised deployments have no stderr capture,
    /// so this is the only place the failure reason is visible.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub last_failure: Option<String>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct HistorianTriggerProgress {
    pub eligible_chunk_tokens: f64,
    pub tail_size_bar: f64,
    pub protected_tail_n_tokens: f64,
    pub protected_start_ordinal: u64,
}

#[derive(Debug, Clone)]
pub(crate) struct ProjectionCacheInput {
    pub projection: Arc<FlatProjection>,
    pub replace_from: usize,
    pub prior_fingerprint: String,
    pub message_retained_bytes: Arc<Vec<usize>>,
}

pub struct TransformWithProjection {
    pub response: TransformResponse,
    pub projection: FlatProjection,
    /// Native attachment uses the same validated tag baseline as the transform, avoiding a
    /// second numbers-only table scan after the response has been built.
    pub tag_numbers: BTreeMap<String, u64>,
    pub scheduler_pass: scheduler::PassDecision,
    pub scheduler_defer_reason: Option<scheduler::SchedulerDeferReason>,
    pub scheduler_drain_latch_active: bool,
    pub boundary_state: BoundaryState,
    pub trim_mismatch: Option<TrimMismatch>,
    pub revert_epoch: u64,
    pub reasoning_watermark: u64,
    /// Whether unmatched native tool shells may use the transition coalescer. The durable marker
    /// records that the compatibility salt already triggered the required cache-invalidating HARD,
    /// so all later replays use the same encoding.
    pub transition_consumed: bool,
    pub mutation_exempt_mid: Option<String>,
    pub lineage_anchor_mid: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TaggableKind {
    Message,
    ToolResult,
}

impl TaggableKind {
    fn as_store_kind(self) -> &'static str {
        match self {
            Self::Message => "message",
            Self::ToolResult => "tool_result",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Channel1Level {
    Gentle,
    Firm,
    Urgent,
}

impl Channel1Level {
    fn as_str(self) -> &'static str {
        match self {
            Self::Gentle => "gentle",
            Self::Firm => "firm",
            Self::Urgent => "urgent",
        }
    }

    fn rank(self) -> u8 {
        match self {
            Self::Gentle => 1,
            Self::Firm => 2,
            Self::Urgent => 3,
        }
    }

    fn parse(value: &str) -> Option<Self> {
        match value {
            "gentle" => Some(Self::Gentle),
            "firm" => Some(Self::Firm),
            "urgent" => Some(Self::Urgent),
            _ => None,
        }
    }
}

