    /// A store compartment covering raw ordinals `start..=end`, ending at message id
    /// `end_id`, rendered at P1 with body `p1`. The m0 baseline is composed from these.
    fn comp(seq: i64, start: i64, end: i64, end_id: &str, p1: &str) -> StoredCompartment {
        StoredCompartment {
            sequence: seq,
            start_message: start,
            end_message: end,
            end_message_id: target_id(end_id),
            title: format!("C{seq}"),
            content: p1.to_string(),
            p1: Some(p1.to_string()),
            importance: 50,
            ..Default::default()
        }
    }

    fn astro_compartments() -> Vec<StoredCompartment> {
        let mut start = 1i64;
        let mut compartments = Vec::with_capacity(48);
        for sequence in 0..48i64 {
            let end = match sequence {
                0 => 200,
                1 => 425,
                _ => {
                    let slots = 48 - sequence;
                    let remaining = 2_400 - start + 1;
                    let size = (remaining + slots - 1) / slots;
                    start + size - 1
                }
            };
            compartments.push(comp(
                sequence,
                start,
                end,
                &format!("m{end}"),
                &format!("ASTRO-C{sequence}"),
            ));
            start = end + 1;
        }
        assert_eq!(compartments.len(), 48);
        assert_eq!(compartments.last().unwrap().end_message, 2_400);
        compartments
    }

    fn astro_request(session_id: &str, tail_end: u64) -> TransformRequest {
        let compartments = astro_compartments();
        let mut messages = compartments
            .iter()
            .map(|compartment| {
                let end = compartment.end_message as u64;
                item(&format!("m{end}"), end, &format!("raw anchor {end}"))
            })
            .collect::<Vec<_>>();
        messages.extend((2_401..=tail_end).map(|ordinal| {
            item(
                &format!("m{ordinal}"),
                ordinal,
                &format!("live tail {ordinal}"),
            )
        }));
        req(session_id, "cfg0", messages)
    }

    pub(crate) fn seed_astro_divergence(
        store: &McStore,
        session_id: &str,
        tail_end: u64,
    ) -> TransformRequest {
        seed_astro_divergence_from_request(store, astro_request(session_id, tail_end))
    }

    fn seed_astro_divergence_from_request(
        store: &McStore,
        request: TransformRequest,
    ) -> TransformRequest {
        store
            .replace_compartments(&request.session_id, &astro_compartments())
            .unwrap();
        let boot = run(store, &request, &spine());
        assert_eq!(boot.action, "HARD");
        assert_eq!(boot.coverage_ordinal, Some(2_400));
        assert_eq!(boot.boundary_id, "m2400#0");

        let loaded = store.load(&request.session_id).unwrap();
        let mut core = loaded.core.clone();
        core.boundary_id = "m425#0".to_string();
        let covered_target = astro_compartments()[2].end_message_id.clone();
        core.frozen_units
            .push(red_unit(&covered_target, "drop", "[dropped stale]"));
        let mut meta = loaded.meta.clone();
        meta.coverage_ordinal = Some(425);
        meta.coverage_start_ordinal = Some(1);
        meta.coverage_compartment_seq = Some(1);
        meta.folded_compartment_seq = 1;
        // Production row read for ses_08df2045… on 2026-08-08: initialized=1,
        // coverage_ordinal=425, m1_revision=1644131851866052375,
        // publication_floor_ordinal=2417 (present, not rewound), and max compartment sequence 47
        // ending near ordinal 2400. The fixture's 2401 floor is intentionally close to that row.
        meta.publication_floor_ordinal = Some(2_401);
        store
            .commit(&request.session_id, loaded.row_version, &core, &meta)
            .unwrap();
        request
    }

