    fn unstamped_opencode_tool_pair(mid: &str, ordinal: u64, call_id: &str) -> CkIngressMessage {
        let native_message = json!({
            "absolute_ordinal": ordinal,
            "info": { "id": mid, "role": "assistant" },
            "parts": [{
                "type": "tool",
                "tool": "read",
                "callID": call_id,
                "state": {
                    "status": "completed",
                    "input": { "path": "pair.txt" },
                    "output": "historical output"
                }
            }]
        });
        let decoded = crate::codec::decode_opencode(&[native_message]);
        let mut projected = decoded.messages.into_iter().next().unwrap();
        projected.ck.content = projected
            .ck
            .content
            .into_iter()
            .map(|block| ck_wire::CkWireBlock::bare(block.kind))
            .collect();
        projected.ck.mark_modified();
        projected
    }

    fn stored_transition_marker_classes(
        store: &McStore,
        session_id: &str,
    ) -> BTreeSet<RendererTransitionClass> {
        let loaded = store.load(session_id).unwrap();
        let marker = loaded
            .core
            .frozen_units
            .iter()
            .find(|unit| unit.key == TRANSITION_CONSUMED_KEY)
            .expect("renderer transition marker must be durable");
        serde_json::from_str(&marker.frozen_payload).unwrap()
    }

    #[test]
    fn served_tool_input_invariant_detects_reduction_envelope_mutation() {
        let mutated = CkWireMessage::from_parts(
            "assistant",
            vec![CkWireBlock::bare(ck_wire::CkKind::ToolCall {
                id: "mutated-envelope-call".to_string(),
                name: "edit".to_string(),
                input: json!({
                    "reduced": true,
                    "summary": r#"{"filePath":"src/lib.rs","oldString":"old","newString":"new"}"#,
                }),
                provider_executed: false,
            })],
            None,
            ck_wire::ProviderExtras::new(),
            ck_wire::HarnessMeta::default(),
        );

        let failure = std::panic::catch_unwind(|| {
            assert_no_foreign_reduction_input_keys([&mutated]);
        })
        .expect_err("the serve-wide invariant must reject the historical envelope shape");
        let output = failure
            .downcast_ref::<String>()
            .cloned()
            .or_else(|| {
                failure
                    .downcast_ref::<&str>()
                    .map(|message| (*message).to_string())
            })
            .expect("invariant failure must record a string diagnostic");
        assert!(output.contains("mutated-envelope-call"));
        assert!(output.contains("foreign reduction-envelope keys"));
        eprintln!("mutation invariant output: {output}");
    }

    #[test]
    fn scheduler_trace_records_every_pass_and_preserves_variable_arm_state() {
        const SESSION: &str = "scheduler-trace";

        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        let messages = vec![item("m1", 1, "stable tail")];
        let low_request = with_usage(req(SESSION, "cfg0", messages.clone()), 10, 100);
        let mut context = pctx("git:proj", "/nonexistent-docs", 101);
        context.cache_ttl = "never".to_string();

        transform(&store, &low_request, &context).unwrap();
        context.now_ms = 102;
        transform(&store, &low_request, &context).unwrap();
        context.now_ms = 103;
        let mut force_request = with_usage(req(SESSION, "cfg0", messages), 90, 100);
        force_request.request_observed_at_ms = Some(100_003);
        force_request.full_array_fingerprint = Some("force-fingerprint".to_string());
        transform(&store, &force_request, &context).unwrap();

        let history = store
            .load_pass_trace(SESSION)
            .unwrap()
            .unwrap()
            .scheduler_history;
        assert_eq!(history.len(), 3, "every accepted pass must be queryable");
        assert_eq!(
            history
                .iter()
                .map(|observation| observation.timestamp_ms)
                .collect::<Vec<_>>(),
            vec![101, 102, 103]
        );
        assert_eq!(history[0].scheduler_decision, "Defer");
        assert_eq!(history[0].canonical_decision.as_deref(), Some("defer"));
        assert_eq!(history[0].defer_reason.as_deref(), Some("scheduler_defer"));
        assert!(!history[0].drain_latch_active);
        assert_eq!(history[1].scheduler_decision, "Defer");
        assert_eq!(history[1].canonical_decision.as_deref(), Some("defer"));
        assert_eq!(history[1].defer_reason.as_deref(), Some("scheduler_defer"));
        assert!(!history[1].drain_latch_active);
        assert_eq!(history[2].scheduler_decision, "Force85");
        assert_eq!(history[2].canonical_decision.as_deref(), Some("execute"));
        assert_eq!(history[2].defer_reason, None);
        assert!(history[2].drain_latch_active);
        assert_ne!(
            history[0].scheduler_decision, history[2].scheduler_decision,
            "the trace must record the scheduler output rather than a constant"
        );
        let incident_window = store
            .load_pass_scheduler_history(SESSION, 102, 103)
            .unwrap();
        assert_eq!(incident_window, history[1..]);
        let correlated = store
            .load_interesting_pass_scheduler_history_by_request_time(SESSION, 100_003)
            .unwrap();
        assert!(
            correlated.is_empty(),
            "a scheduler arm without a reduction or divergence is not interesting"
        );
    }

    #[test]
    fn scheduler_trace_keeps_mid_turn_downgrades_in_the_defer_pass_class() {
        let genuine_defer = pass_scheduler_observation(
            scheduler::PassDecision::Defer,
            Some(scheduler::SchedulerDeferReason::SchedulerDefer),
            false,
            201,
        );
        let boundary_defer = pass_scheduler_observation(
            scheduler::PassDecision::Defer,
            Some(scheduler::SchedulerDeferReason::MidTurnBoundary),
            false,
            202,
        );

        for observation in [&genuine_defer, &boundary_defer] {
            assert_eq!(observation.scheduler_decision, "Defer");
            assert_eq!(observation.canonical_decision.as_deref(), Some("defer"));
        }
        assert_eq!(
            genuine_defer.defer_reason.as_deref(),
            Some("scheduler_defer")
        );
        assert_eq!(
            boundary_defer.defer_reason.as_deref(),
            Some("mid_turn_boundary")
        );
    }

    #[test]
    fn served_fingerprint_block_ids_pin_flat_mid_index_format() {
        let single = ServedMessage::from_message(text_message("single", "one"));
        let multiple = ServedMessage::from_message(CkWireMessage::from_parts(
            "user",
            vec![
                CkWireBlock::bare(ck_wire::CkKind::Text {
                    text: "first".to_string(),
                }),
                CkWireBlock::bare(ck_wire::CkKind::Text {
                    text: "second".to_string(),
                }),
            ],
            None,
            ck_wire::ProviderExtras::new(),
            ck_wire::HarnessMeta {
                harness_id: Some("multiple".to_string()),
                ..Default::default()
            },
        ));
        let synthetic = ServedMessage::from_message(CkWireMessage::synthetic_user_text(
            "synthetic".to_string(),
        ));

        let block_ids = served_output_fingerprints(&[single, multiple, synthetic])
            .into_iter()
            .map(|fingerprint| fingerprint.block_id)
            .collect::<Vec<_>>();
        assert_eq!(
            block_ids,
            ["single#0", "multiple#0", "multiple#1", "mc_m0#0"]
        );
    }

    #[test]
    fn served_fingerprint_records_cold_start_and_attributes_middle_changes() {
        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        let session = "served-divergence";
        let baseline_messages = vec![item("a", 0, "a"), item("b", 1, "b"), item("c", 2, "c")];
        let baseline_request = req(session, "cfg0", baseline_messages.clone());

        let first = run(&store, &baseline_request, &spine());
        assert!(first.first_divergence.is_none());
        assert!(!store
            .load(session)
            .unwrap()
            .meta
            .served_output_fingerprint
            .is_empty());

        let stable = run(&store, &baseline_request, &spine());
        assert!(stable.first_divergence.is_none());
        assert_eq!(stable.row_version, first.row_version);
        assert!(!stable.committed);

        let inserted_request = req(
            session,
            "cfg0",
            vec![
                item("a", 0, "a"),
                item("inserted", 1, "inserted"),
                item("b", 2, "b"),
                item("c", 3, "c"),
            ],
        );
        let inserted = run(&store, &inserted_request, &spine());
        let inserted_divergence = inserted.first_divergence.as_ref().unwrap();
        assert_eq!(
            inserted_divergence.kind,
            divergence::DivergenceKind::Inserted
        );
        assert_eq!(inserted_divergence.block_id_old.as_deref(), Some("b#0"));
        assert_eq!(
            inserted_divergence.block_id_new.as_deref(),
            Some("inserted#0")
        );
        let trace = store.load_pass_trace(session).unwrap().unwrap();
        let inserted_json = serde_json::to_string(inserted_divergence).unwrap();
        assert_eq!(
            trace.first_divergence.as_deref(),
            Some(inserted_json.as_str())
        );

        let removed_request = req(session, "cfg0", vec![item("a", 0, "a"), item("c", 3, "c")]);
        let removed = run(&store, &removed_request, &spine());
        let removed_divergence = removed.first_divergence.as_ref().unwrap();
        assert_eq!(removed_divergence.kind, divergence::DivergenceKind::Removed);
        assert_eq!(
            removed_divergence.block_id_old.as_deref(),
            Some("inserted#0")
        );
        assert_eq!(removed_divergence.block_id_new.as_deref(), Some("c#0"));

        let stable_after_divergence = run(&store, &removed_request, &spine());
        assert!(stable_after_divergence.first_divergence.is_none());
        let trace = store.load_pass_trace(session).unwrap().unwrap();
        assert!(trace.first_divergence.is_none());
        let last_divergence: Value =
            serde_json::from_str(trace.last_divergence.as_deref().unwrap()).unwrap();
        assert_eq!(
            last_divergence["divergence"],
            serde_json::to_value(removed_divergence).unwrap()
        );
        assert!(last_divergence["pass_id"].is_number());
        assert!(last_divergence["timestamp_ms"].is_number());
    }

    fn comparable_response(response: TransformResponse) -> Value {
        let mut wire = serde_json::to_value(response).unwrap();
        wire.as_object_mut().unwrap().remove("timings");
        wire
    }

    fn assert_same_tag_mint_work(left: &TagMintWork, right: &TagMintWork) {
        assert_eq!(left.candidate_count, right.candidate_count);
        assert_eq!(left.tokenized_bytes, right.tokenized_bytes);
        assert_eq!(left.inputs.len(), right.inputs.len());
        for (a, b) in left.inputs.iter().zip(right.inputs.iter()) {
            assert_eq!(a.block_id, b.block_id);
            assert_eq!(a.kind, b.kind);
            assert_eq!(a.token_count, b.token_count);
            assert_eq!(a.source_bytes, b.source_bytes);
        }
    }

    /// Projection content_hash reuse and tag-mint frontier scanning must not change
    /// served bytes or divergence attribution rows versus the prior full-rehash /
    /// full-scan algorithms.
    #[test]
    fn parked_p2_fingerprint_reuse_and_tag_frontier_match_baseline() {
        // --- unit: fingerprint reuse vs forced rehash on a mixed message ---
        let multi = wire_item("user", "multi", 0, &["alpha", "beta"]);
        let multi_proj = project_messages(std::slice::from_ref(&multi)).unwrap();
        let multi_blocks: Vec<&FlatBlock> = multi_proj.blocks.iter().collect();
        let mut multi_rendered = multi.ck.clone();
        // Overlay only the second text block so the first stays projection-identical.
        if let ck_wire::CkKind::Text { text } = &mut multi_rendered.content[1].kind {
            *text = format!("\u{a7}2\u{a7} {text}");
        }
        multi_rendered.content[1].mark_modified();
        multi_rendered.mark_modified();

        let reused =
            ServedMessage::from_message_reusing(multi_rendered.clone(), Some(&multi_blocks));
        let baseline = ServedMessage::from_message(multi_rendered);
        assert_eq!(
            reused.block_fingerprints.as_ref(),
            baseline.block_fingerprints.as_ref(),
            "projection hash reuse must yield the same divergence fingerprints"
        );
        assert_eq!(
            reused.canonical_bytes.as_ref(),
            baseline.canonical_bytes.as_ref(),
            "canonical served bytes must stay identical under hash reuse"
        );
        // First block must actually hit the reuse path (same digest as FlatBlock).
        assert_eq!(
            reused.block_fingerprints[0].0,
            ck_wire::fingerprint_digest(&multi_blocks[0].content_hash)
        );
        assert_ne!(
            reused.block_fingerprints[1].0,
            ck_wire::fingerprint_digest(&multi_blocks[1].content_hash),
            "overlaid block must re-hash rather than reuse the pre-overlay digest"
        );

        // --- unit: tag-mint frontier memo vs full scan across append-only passes ---
        let mut memo = TagMintFrontierMemo::default();
        let core = CoreState::default();
        let pass1 = project_messages(&[
            wire_item("user", "t0", 0, &["first"]),
            wire_item("assistant", "t1", 1, &["second"]),
        ])
        .unwrap();
        let empty_tags: HashSet<&str> = HashSet::new();
        let full1 = tag_mint_inputs(&pass1, &core, None, &empty_tags);
        let memo1 = tag_mint_inputs_from(
            &pass1,
            &core,
            None,
            None,
            &empty_tags,
            None,
            None,
            Some(&mut memo),
        );
        assert_same_tag_mint_work(&memo1, &full1);
        assert!(memo.frontier > 0);

        let owned_ids: Vec<String> = full1.inputs.iter().map(|i| i.block_id.clone()).collect();
        let existing: HashSet<&str> = owned_ids.iter().map(String::as_str).collect();

        let pass2 = project_messages(&[
            wire_item("user", "t0", 0, &["first"]),
            wire_item("assistant", "t1", 1, &["second"]),
            wire_item("user", "t2", 2, &["third append"]),
        ])
        .unwrap();
        let full2 = tag_mint_inputs(&pass2, &core, None, &existing);
        let memo2 = tag_mint_inputs_from(
            &pass2,
            &core,
            None,
            None,
            &existing,
            None,
            None,
            Some(&mut memo),
        );
        assert_same_tag_mint_work(&memo2, &full2);
        assert_eq!(memo2.inputs.len(), 1, "only the appended block mints");

        // --- e2e: tags + divergence-active mixed fixture ---
        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        let session = "p2-fingerprints-frontier";
        let bootstrap = active_cc_req(
            session,
            "cfg0",
            vec![
                wire_item("user", "m0", 0, &["plan the work"]),
                wire_item("assistant", "m1", 1, &["working on it"]),
            ],
        );
        let first = run(&store, &bootstrap, &spine());
        assert_eq!(first.surface_state, SurfaceState::Transition);
        assert!(first.first_divergence.is_none());

        let active = active_cc_req(
            session,
            "cfg0",
            vec![
                wire_item("user", "m0", 0, &["plan the work"]),
                wire_item("assistant", "m1", 1, &["working on it"]),
                wire_item("user", "m2", 2, &["continue with details"]),
            ],
        );
        let second = run(&store, &active, &spine());
        assert_eq!(second.surface_state, SurfaceState::Active);
        let joined = serde_json::to_string(second.messages()).unwrap();
        assert!(
            joined.contains("\u{a7}1\u{a7}"),
            "active tagging must prefix served text: {joined}"
        );

        // Stable defer: no divergence, tags retained, output byte-stable.
        let stable = run(&store, &active, &spine());
        assert!(stable.first_divergence.is_none());
        assert_eq!(
            serde_json::to_value(stable.messages()).unwrap(),
            serde_json::to_value(second.messages()).unwrap()
        );

        // Divergence-active rewrite of a middle message.
        let diverged = active_cc_req(
            session,
            "cfg0",
            vec![
                wire_item("user", "m0", 0, &["plan the work"]),
                wire_item("assistant", "m1", 1, &["CHANGED middle content"]),
                wire_item("user", "m2", 2, &["continue with details"]),
            ],
        );
        let third = run(&store, &diverged, &spine());
        let row = third
            .first_divergence
            .as_ref()
            .expect("middle content change must attribute");
        assert_eq!(row.kind, divergence::DivergenceKind::ContentChanged);
        assert_eq!(row.block_id_old.as_deref(), Some("m1#0"));
        assert_eq!(row.block_id_new.as_deref(), Some("m1#0"));

        // Fingerprints stored for the diverged pass match a forced-rehash rebuild of
        // the same served messages (proves attribution rows stay on the same basis).
        let loaded = store.load(session).unwrap();
        let forced_messages: Vec<ServedMessage> = third
            .messages()
            .iter()
            .map(|m| ServedMessage::from_message(std::ops::Deref::deref(m).clone()))
            .collect();
        let forced_fps = served_output_fingerprints(&forced_messages);
        assert_eq!(
            forced_fps, loaded.meta.served_output_fingerprint,
            "stored divergence fingerprints must match forced re-hash of served output"
        );
    }

    fn synthetic_text(r: &TransformResponse, index: usize) -> &str {
        ck_wire::text_from_message(
            r.messages()
                .iter()
                .filter(|m| m.meta.synthetic)
                .nth(index)
                .unwrap(),
        )
        .unwrap()
    }

    fn m0_bytes(r: &TransformResponse) -> &str {
        synthetic_text(r, 0)
    }
    fn m1_bytes(r: &TransformResponse) -> &str {
        synthetic_text(r, 1)
    }
    fn tail_ids(r: &TransformResponse) -> Vec<&str> {
        r.messages()
            .iter()
            .filter(|m| !m.meta.synthetic)
            .map(|m| m.meta.harness_id.as_deref().unwrap_or(""))
            .collect()
    }

    fn ingress_from_ck(messages: Vec<CkWireMessage>) -> Vec<CkIngressMessage> {
        messages
            .into_iter()
            .enumerate()
            .map(|(i, ck)| CkIngressMessage {
                mid: format!("m{i}"),
                ordinal: i as u64 + 1,
                ck,
            })
            .collect()
    }

