    #[test]
    fn reasoning_cutoff_batches_on_one_fold_and_survives_restart() {
        fn signed_assistant(mid: &str, ordinal: u64) -> CkIngressMessage {
            CkIngressMessage {
                mid: mid.to_string(),
                ordinal,
                ck: CkWireMessage::from_parts(
                    "assistant",
                    vec![
                        ck_wire::CkWireBlock::bare(ck_wire::CkKind::Reasoning {
                            text: format!("thinking-{mid}"),
                            signature: Some(format!("signature-{mid}")),
                        }),
                        ck_wire::CkWireBlock::bare(ck_wire::CkKind::Text {
                            text: format!("answer-{mid}"),
                        }),
                    ],
                    None,
                    ck_wire::ProviderExtras::new(),
                    ck_wire::HarnessMeta {
                        harness_id: Some(mid.to_string()),
                        ..Default::default()
                    },
                ),
            }
        }

        fn request(messages: Vec<CkIngressMessage>) -> TransformRequest {
            let mut request = active_opencode_req("reasoning-batch", "cfg0", messages);
            request.provider_id = Some("anthropic".to_string());
            request.serve_native = true;
            request.clear_reasoning_age = 3;
            with_usage(request, 70, 100)
        }

        fn reasoning_text<'a>(response: &'a TransformResponse, mid: &str) -> &'a str {
            response
                .messages()
                .iter()
                .find(|message| message.meta.harness_id.as_deref() == Some(mid))
                .and_then(|message| {
                    message.content.iter().find_map(|block| match &block.kind {
                        ck_wire::CkKind::Reasoning { text, .. } => Some(text.as_str()),
                        _ => None,
                    })
                })
                .unwrap_or_else(|| panic!("missing reasoning for {mid}"))
        }

        let dir = tempfile::tempdir().unwrap();
        let db = store(dir.path());
        db.replace_compartments(
            "reasoning-batch",
            &[comp(1, 1, 1, "anchor", "first coverage")],
        )
        .unwrap();
        let mut messages = vec![
            item("anchor", 1, "covered"),
            item("fold-target", 2, "fold later"),
            signed_assistant("assistant-a", 3),
            item("gap-b", 4, "separator"),
            signed_assistant("assistant-b", 5),
        ];

        let transition = run(&db, &request(messages.clone()), &spine());
        assert_eq!(transition.action, "HARD");
        let tagged = run(&db, &request(messages.clone()), &spine());
        assert_eq!(tagged.action, "SOFT+");
        assert_eq!(
            reasoning_text(&tagged, "assistant-a"),
            "thinking-assistant-a"
        );
        assert_eq!(
            reasoning_text(&tagged, "assistant-b"),
            "thinking-assistant-b"
        );
        assert_eq!(
            db.load("reasoning-batch")
                .unwrap()
                .meta
                .reasoning_cleared_through_tag,
            2,
            "the bootstrap HARD records its pre-reasoning cutoff while preserving newer signatures"
        );

        messages.push(item("gap-c", 6, "separator"));
        messages.push(signed_assistant("assistant-c", 7));
        let before_fold = run(&db, &request(messages.clone()), &spine());
        assert_eq!(before_fold.action, "SOFT+");
        assert!(before_fold.first_divergence.is_none());
        assert_eq!(
            reasoning_text(&before_fold, "assistant-a"),
            "thinking-assistant-a"
        );
        assert_eq!(
            reasoning_text(&before_fold, "assistant-b"),
            "thinking-assistant-b"
        );

        db.replace_compartments(
            "reasoning-batch",
            &[
                comp(1, 1, 1, "anchor", "first coverage"),
                comp(2, 2, 2, "fold-target", "second coverage"),
            ],
        )
        .unwrap();
        messages.push(item("gap-d", 8, "separator"));
        messages.push(signed_assistant("assistant-d", 9));
        let fold = run(&db, &request(messages.clone()), &spine());
        assert_eq!(fold.action, "SOFT");
        assert_eq!(fold.materialize_reason.as_deref(), Some("coverage_fold"));
        assert!(
            fold.first_divergence.is_some(),
            "the coverage fold is the one bust"
        );
        assert_eq!(reasoning_text(&fold, "assistant-a"), "");
        assert_eq!(reasoning_text(&fold, "assistant-b"), "");
        assert_eq!(reasoning_text(&fold, "assistant-c"), "thinking-assistant-c");
        assert_eq!(reasoning_text(&fold, "assistant-d"), "thinking-assistant-d");
        assert_eq!(
            db.load("reasoning-batch")
                .unwrap()
                .meta
                .reasoning_cleared_through_tag,
            6,
            "the fold captures every current-pass tag in one cutoff"
        );

        drop(db);
        let restarted = store(dir.path());
        messages.push(item("gap-e", 10, "separator"));
        messages.push(signed_assistant("assistant-e", 11));
        let after_fold = run(&restarted, &request(messages), &spine());
        assert_eq!(after_fold.action, "SOFT+");
        assert!(
            after_fold.first_divergence.is_none(),
            "the post-fold pass may append but must not mutate the served prefix"
        );
        assert_eq!(reasoning_text(&after_fold, "assistant-a"), "");
        assert_eq!(reasoning_text(&after_fold, "assistant-b"), "");
        assert_eq!(
            reasoning_text(&after_fold, "assistant-c"),
            "thinking-assistant-c"
        );
        assert_eq!(
            reasoning_text(&after_fold, "assistant-d"),
            "thinking-assistant-d"
        );
        assert_eq!(
            reasoning_text(&after_fold, "assistant-e"),
            "thinking-assistant-e"
        );
        assert_eq!(
            restarted
                .load("reasoning-batch")
                .unwrap()
                .meta
                .reasoning_cleared_through_tag,
            6,
            "a restart must replay the prior bust cutoff instead of deriving maxTag-age"
        );
    }

    #[test]
    fn claude_code_reasoning_age_waits_for_bust_then_removes_whole_signed_blocks() {
        fn signed_assistant(mid: &str, ordinal: u64) -> CkIngressMessage {
            let mut content = vec![CkWireBlock::bare(ck_wire::CkKind::Reasoning {
                text: format!("thinking-{mid}"),
                signature: Some(format!("signature-{mid}")),
            })];
            if mid == "old" {
                content.push(CkWireBlock::bare(ck_wire::CkKind::RedactedReasoning {
                    data: "redacted-old".to_string(),
                }));
            }
            content.push(CkWireBlock::bare(ck_wire::CkKind::Text {
                text: format!("answer-{mid}"),
            }));
            CkIngressMessage {
                mid: mid.to_string(),
                ordinal,
                ck: CkWireMessage::from_parts(
                    "assistant",
                    content,
                    None,
                    ck_wire::ProviderExtras::new(),
                    ck_wire::HarnessMeta {
                        harness_id: Some(mid.to_string()),
                        ..Default::default()
                    },
                ),
            }
        }

        fn reasoning_count(response: &TransformResponse, mid: &str) -> usize {
            response
                .messages()
                .iter()
                .find(|message| message.meta.harness_id.as_deref() == Some(mid))
                .unwrap_or_else(|| panic!("missing assistant {mid}"))
                .content
                .iter()
                .filter(|block| is_reasoning_block(block))
                .count()
        }

        fn request(config: &str, clear_reasoning_age: u64) -> TransformRequest {
            let messages = vec![
                signed_assistant("old", 1),
                wire_item(
                    "assistant",
                    "adjacent-plain",
                    2,
                    &["plain assistant sibling"],
                ),
                item("separator", 3, "separate the latest response"),
                signed_assistant("latest", 4),
            ];
            let mut request = active_cc_req("cc-reasoning-age", config, messages);
            request.clear_reasoning_age = clear_reasoning_age;
            request
        }

        let dir = tempfile::tempdir().unwrap();
        let db = store(dir.path());
        let baseline = run(&db, &request("cfg0", 100), &spine());
        assert_eq!(baseline.action, "HARD");
        assert_eq!(reasoning_count(&baseline, "old"), 2);
        let baseline_messages = baseline
            .messages()
            .iter()
            .cloned()
            .map(ServedMessage::into_message)
            .collect::<Vec<_>>();
        assert!(
            has_reasoning_assistant_adjacency(&baseline_messages),
            "the fixture must exercise an adjacency that removal resolves"
        );
        let baseline_bytes = serde_json::to_vec(baseline.messages()).unwrap();

        let waiting_request = request("cfg0", 2);
        let waiting = run(&db, &waiting_request, &spine());
        assert_eq!(waiting.action, "SOFT+");
        assert_eq!(
            serde_json::to_vec(waiting.messages()).unwrap(),
            baseline_bytes
        );
        let waiting_state = db.load("cc-reasoning-age").unwrap();
        assert_eq!(waiting_state.meta.reasoning_cleared_through_tag, 0);
        assert!(waiting_state
            .core
            .frozen_units
            .iter()
            .all(|unit| unit.key != "strip:reasoning_age:old"));

        let bust_request = request("cfg1", 2);
        let applied = run(&db, &bust_request, &spine());
        assert_eq!(applied.action, "HARD");
        assert_eq!(reasoning_count(&applied, "old"), 0);
        assert_eq!(reasoning_count(&applied, "latest"), 1);
        assert!(tail_bytes(&applied, "old").contains("§1§ answer-old"));
        assert!(
            !has_reasoning_assistant_adjacency(
                &applied
                    .messages()
                    .iter()
                    .cloned()
                    .map(ServedMessage::into_message)
                    .collect::<Vec<_>>()
            ),
            "whole-block removal must still pass the reasoning-adjacency skeleton check"
        );
        let applied_state = db.load("cc-reasoning-age").unwrap();
        // The latest text now owns tag 4 on first sight; age 2 freezes cutoff 2.
        assert_eq!(applied_state.meta.reasoning_cleared_through_tag, 2);
        assert!(applied_state
            .core
            .frozen_units
            .iter()
            .any(|unit| unit.key == "strip:reasoning_age:old"));
        let applied_bytes = serde_json::to_vec(applied.messages()).unwrap();

        let replay = run(&db, &bust_request, &spine());
        assert_eq!(replay.action, "SOFT+");
        assert_eq!(
            serde_json::to_vec(replay.messages()).unwrap(),
            applied_bytes
        );
        assert!(!replay.committed, "a frozen replay needs no state write");

        drop(db);
        let restarted = store(dir.path());
        let cold_replay = run(&restarted, &bust_request, &spine());
        assert_eq!(cold_replay.action, "SOFT+");
        assert_eq!(
            serde_json::to_vec(cold_replay.messages()).unwrap(),
            applied_bytes
        );
    }

    #[test]
    fn opencode_d2_watermark_persists_and_defer_does_not_recompute_it() {
        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        let assistant = CkWireMessage::from_parts(
            "assistant",
            vec![ck_wire::CkWireBlock::bare(ck_wire::CkKind::Reasoning {
                text: "old thinking".to_string(),
                signature: Some("old signature".to_string()),
            })],
            None,
            ck_wire::ProviderExtras::new(),
            ck_wire::HarnessMeta {
                harness_id: Some("assistant".to_string()),
                ..Default::default()
            },
        );
        let user = CkWireMessage::from_parts(
            "user",
            vec![ck_wire::CkWireBlock::bare(ck_wire::CkKind::Text {
                text: "new prompt".to_string(),
            })],
            None,
            ck_wire::ProviderExtras::new(),
            ck_wire::HarnessMeta {
                harness_id: Some("user".to_string()),
                ..Default::default()
            },
        );
        let mut request = req(
            "d2-watermark",
            "cfg0",
            vec![
                CkIngressMessage {
                    mid: "assistant".to_string(),
                    ordinal: 1,
                    ck: assistant,
                },
                CkIngressMessage {
                    mid: "user".to_string(),
                    ordinal: 10,
                    ck: user,
                },
            ],
        );
        request.serializer_profile = SerializerProfile::OpencodeAiSdk.wire_id().to_string();
        request.provider_id = Some("anthropic".to_string());
        request.serve_native = true;
        request.clear_reasoning_age = 5;

        let first = transform(&store, &request, &pctx("git:proj", "/nonexistent-docs", 0)).unwrap();
        assert_eq!(
            store
                .load("d2-watermark")
                .unwrap()
                .meta
                .reasoning_cleared_through_ordinal,
            0
        );
        assert!(first.committed);

        let second =
            transform(&store, &request, &pctx("git:proj", "/nonexistent-docs", 0)).unwrap();
        assert_eq!(second.action, "SOFT+");
        assert_eq!(
            store
                .load("d2-watermark")
                .unwrap()
                .meta
                .reasoning_cleared_through_ordinal,
            0,
            "untagged reasoning has unknown age and must remain uncleared"
        );
        assert!(!second.committed);
    }

    #[test]
    fn opencode_d2_clears_historical_reasoning_after_codec_and_replays_stably() {
        fn assistant(mid: &str) -> CkWireMessage {
            CkWireMessage::from_parts(
                "assistant",
                vec![ck_wire::CkWireBlock::bare(ck_wire::CkKind::Reasoning {
                    text: format!("thinking-{mid}"),
                    signature: Some(format!("signature-{mid}")),
                })],
                None,
                ck_wire::ProviderExtras::new(),
                ck_wire::HarnessMeta {
                    harness_id: Some(mid.to_string()),
                    ..Default::default()
                },
            )
        }

        let old = assistant("old");
        let latest = assistant("latest");
        let served = vec![old.clone(), latest.clone()];
        let ingress = vec![
            CkIngressMessage {
                mid: "old".to_string(),
                ordinal: 1,
                ck: old,
            },
            CkIngressMessage {
                mid: "latest".to_string(),
                ordinal: 60,
                ck: latest,
            },
        ];
        let mut native = vec![
            json!({
                "info": { "id": "old", "role": "assistant" },
                "parts": [{
                    "type": "reasoning",
                    "text": "thinking-old",
                    "metadata": { "signature": "signature-old" }
                }]
            }),
            json!({
                "info": { "id": "latest", "role": "assistant" },
                "parts": [{
                    "type": "reasoning",
                    "text": "thinking-latest",
                    "metadata": { "signature": "signature-latest" }
                }]
            }),
        ];

        assert_eq!(
            clear_served_native_reasoning(
                SerializerProfile::OpencodeAiSdk,
                true,
                &mut native,
                &served,
                &ingress,
                60,
                false,
            ),
            1,
            "the newest assistant is exempt even after completion"
        );
        assert_eq!(native[0]["parts"][0], json!({ "type": "text", "text": "" }));
        assert_eq!(native[1]["parts"][0]["text"], "thinking-latest");
        let first_pass = native.clone();
        assert_eq!(
            clear_served_native_reasoning(
                SerializerProfile::OpencodeAiSdk,
                true,
                &mut native,
                &served,
                &ingress,
                60,
                false,
            ),
            0
        );
        assert_eq!(native, first_pass, "defer replay must be byte-stable");

        let mut in_flight = vec![
            json!({
                "info": { "id": "old", "role": "assistant" },
                "parts": [{ "type": "reasoning", "text": "thinking-old" }]
            }),
            json!({
                "info": { "id": "latest", "role": "assistant" },
                "parts": [{ "type": "reasoning", "text": "thinking-latest" }]
            }),
        ];
        assert_eq!(
            clear_served_native_reasoning(
                SerializerProfile::OpencodeAiSdk,
                true,
                &mut in_flight,
                &served,
                &ingress,
                60,
                true,
            ),
            1
        );
        assert_eq!(in_flight[0]["parts"][0]["text"], "");
        assert_eq!(in_flight[1]["parts"][0]["text"], "thinking-latest");
    }

