    #[cfg(not(debug_assertions))]
    #[test]
    fn duplicate_tool_use_belt_drops_later_owner_and_result_in_release() {
        let messages = vec![
            ServedMessage::from_message(assistant_tool_call("one", 1, "duplicate").ck),
            ServedMessage::from_message(tool_result("one-result", 2, "duplicate", "first").ck),
            ServedMessage::from_message(assistant_tool_call("two", 3, "duplicate").ck),
            ServedMessage::from_message(tool_result("two-result", 4, "duplicate", "second").ck),
        ];

        let healed = enforce_unique_tool_use_ids(messages, "belt-release-test");

        assert!(duplicate_tool_use_locations(&healed).is_empty());
        assert_eq!(healed.len(), 2);
        assert_eq!(healed[0].meta.harness_id.as_deref(), Some("one"));
        assert_eq!(healed[1].meta.harness_id.as_deref(), Some("one-result"));

        let healed_ck = healed
            .iter()
            .map(|message| message.deref().clone())
            .collect::<Vec<_>>();
        let mut request = req(
            "belt-release-native",
            "cfg0",
            ingress_from_ck(healed_ck.clone()),
        );
        request.serializer_profile = "opencode-aisdk".to_string();
        request.serve_native = true;
        request.full_array_fingerprint = Some("belt-release-fp".to_string());
        let cache = Mutex::new(crate::NativeAttachmentCache::new(1024 * 1024));
        let mut first = TransformResponse::passthrough(
            healed_ck.clone(),
            request.full_array_fingerprint.clone(),
        );
        let first_stats = crate::attach_native_messages_incremental(
            &mut first,
            &request,
            0,
            &BTreeMap::new(),
            None,
            None,
            true,
            None,
            0,
            &cache,
            crate::NativeCacheKeyMode::Normal,
        );
        assert_eq!(first_stats.encoded_messages, healed_ck.len());
        let native = first.native_messages.as_ref().unwrap();
        let tool_ids = native
            .iter()
            .flat_map(|message| message["parts"].as_array().into_iter().flatten())
            .filter_map(|part| part["callID"].as_str())
            .collect::<Vec<_>>();
        assert_eq!(
            tool_ids.len(),
            tool_ids.iter().copied().collect::<HashSet<_>>().len()
        );
        assert_eq!(tool_ids, vec!["duplicate"]);

        let mut replay = TransformResponse::passthrough(
            healed_ck.clone(),
            request.full_array_fingerprint.clone(),
        );
        let replay_stats = crate::attach_native_messages_incremental(
            &mut replay,
            &request,
            0,
            &BTreeMap::new(),
            None,
            None,
            true,
            None,
            0,
            &cache,
            crate::NativeCacheKeyMode::Normal,
        );
        assert_eq!(replay_stats.reused_messages, healed_ck.len());
        assert_eq!(replay_stats.encoded_messages, 0);
        assert_eq!(replay.native_messages, first.native_messages);
    }

    #[test]
    fn synthetic_todo_compose_at_bust_freezes_position_across_defer_tail_growth() {
        let dir = tempfile::tempdir().unwrap();
        let s = store(dir.path());
        s.replace_compartments("freeze", &[comp(1, 1, 1, "a", "SUMMARY")])
            .unwrap();
        let todos = json!([{ "content": "Plan", "status": "pending", "priority": "high" }]);
        let bust_items = vec![
            item("a", 1, "raw"),
            todowrite_call("todo", 2, todos.clone()),
        ];
        let bust = run(&s, &req("freeze", "cfg0", bust_items.clone()), &spine());

        assert_eq!(bust.action, "HARD");
        assert_eq!(
            synthetic_todo_index(&bust),
            message_index(&bust, "todo") + 1
        );
        let bust_prefix = prefix_through_synthetic_todo(&bust);

        let defer_items = vec![
            item("a", 1, "raw"),
            todowrite_call("todo", 2, todos),
            item("later1", 3, "new tail 1"),
            item("later2", 4, "new tail 2"),
        ];
        let defer = run(&s, &req("freeze", "cfg0", defer_items), &spine());

        assert_eq!(defer.action, "SOFT+");
        assert_eq!(
            synthetic_todo_index(&defer),
            message_index(&defer, "todo") + 1
        );
        assert!(message_index(&defer, "later1") > synthetic_todo_index(&defer) + 1);
        assert!(message_index(&defer, "later2") > synthetic_todo_index(&defer) + 1);
        assert_eq!(prefix_through_synthetic_todo(&defer), bust_prefix);
    }

