    #[test]
    fn tag_prefix_strip_is_a_byte_exact_inverse() {
        let corpus = [
            "",
            "plain",
            "  leading whitespace",
            "\t\nline",
            "§7§ forged other tag",
            "§42§ genuine same-looking content",
            "é日🙂",
            "§not-a-tag§ x",
        ];
        for content in corpus {
            let tagged = prepend_tag(42, content);
            assert_eq!(strip_tag_prefix(&tagged, 42).as_bytes(), content.as_bytes());
            if !content.starts_with("§42§ ") {
                assert_eq!(strip_tag_prefix(content, 42).as_bytes(), content.as_bytes());
            }
        }
        assert_eq!(
            strip_tag_prefix("§7§ forged other tag", 42),
            "§7§ forged other tag"
        );
        assert_eq!(
            strip_tag_prefix("§42§ §42§ user content", 42),
            "§42§ user content",
            "only one registered prefix occurrence is removed"
        );
    }

    #[test]
    fn temporal_gap_format_matches_typescript_goldens() {
        let fixtures = [
            (0, None),
            (299_999, None),
            (300_000, Some("<!-- +5m -->\n")),
            (12 * 60 * 1_000, Some("<!-- +12m -->\n")),
            ((2 * 60 * 60 + 15 * 60) * 1_000, Some("<!-- +2h 15m -->\n")),
            (24 * 60 * 60 * 1_000, Some("<!-- +1d -->\n")),
            (
                (3 * 24 * 60 * 60 + 4 * 60 * 60) * 1_000,
                Some("<!-- +3d 4h -->\n"),
            ),
            (7 * 24 * 60 * 60 * 1_000, Some("<!-- +1w -->\n")),
            (
                (2 * 7 * 24 * 60 * 60 + 3 * 24 * 60 * 60) * 1_000,
                Some("<!-- +2w 3d -->\n"),
            ),
        ];
        for (gap_ms, expected) in fixtures {
            assert_eq!(temporal_gap_prefix(gap_ms).as_deref(), expected);
        }
    }

    #[test]
    fn temporal_gap_dump_golden_backfills_all_historical_markers_in_one_transition() {
        run_active_surface_test(|| {
            let golden: Value =
                serde_json::from_str(include_str!("../testdata/temporal-parity-golden.json"))
                    .expect("temporal parity golden");
            assert_eq!(golden["schema"], 1);
            assert_eq!(golden["generator_version"], 1);
            let fixture = &golden["cases"][0];
            let messages: Vec<CkIngressMessage> =
                serde_json::from_value(fixture["encoded_input"].clone())
                    .expect("golden CK ingress");
            let expected: BTreeMap<String, String> =
                serde_json::from_value(fixture["expected_text_by_mid"].clone())
                    .expect("golden expected text");

            let dir = tempfile::tempdir().unwrap();
            let s = store(dir.path());
            let mut untimed = messages.clone();
            for message in &mut untimed {
                message.ck.meta.created_at_ms = None;
                message.ck.meta.completed_at_ms = None;
            }
            let baseline_request = active_opencode_req("temporal-dump-golden", "cfg0", untimed);
            run(&s, &baseline_request, &spine());
            run(&s, &baseline_request, &spine());

            let request = active_opencode_req("temporal-dump-golden", "cfg0", messages.clone());
            let transitioned = transform(
                &s,
                &request,
                &pctx("git:proj", "/nonexistent-docs", 50_569_000),
            )
            .unwrap();
            assert_eq!(transitioned.action, "HARD");
            let tags = s
                .load_tags_for_session("temporal-dump-golden")
                .unwrap()
                .into_iter()
                .map(|row| (row.block_id, row.tag_number))
                .collect::<HashMap<_, _>>();
            for (mid, expected_text) in &expected {
                let actual = tail_bytes(&transitioned, mid);
                let tag = tags
                    .get(&format!("{mid}#0"))
                    .unwrap_or_else(|| panic!("missing tag for {mid}"));
                assert_eq!(
                    strip_tag_prefix(actual, *tag),
                    expected_text.as_str(),
                    "{mid}"
                );
            }
            assert_eq!(
                s.load_temporal_marks("temporal-dump-golden")
                    .unwrap()
                    .into_iter()
                    .filter(|row| !row.marker_text.is_empty())
                    .count(),
                2,
                "both historical markers must commit in the transition fold"
            );

            let transitioned_bytes = serde_json::to_vec(transitioned.messages()).unwrap();
            let transitioned_row = transitioned.row_version;
            let replay = transform(
                &s,
                &request,
                &pctx("git:proj", "/nonexistent-docs", 50_869_000),
            )
            .unwrap();
            assert_ne!(replay.action, "HARD");
            assert_eq!(replay.row_version, transitioned_row);
            assert_eq!(
                serde_json::to_vec(replay.messages()).unwrap(),
                transitioned_bytes
            );
        });
    }

    #[test]
    fn temporal_gap_overlay_replays_and_false_window_is_verbatim() {
        run_active_surface_test(|| {
            let dir = tempfile::tempdir().unwrap();
            let s = store(dir.path());
            let first_messages = vec![wire_item("user", "m1", 1, &["start"])];
            let first_request = active_cc_req("temporal", "cfg0", first_messages.clone());
            transform(
                &s,
                &first_request,
                &pctx("git:proj", "/nonexistent-docs", 1_000),
            )
            .unwrap();
            transform(
                &s,
                &first_request,
                &pctx("git:proj", "/nonexistent-docs", 1_000),
            )
            .unwrap();

            let mut with_assistant = first_messages;
            with_assistant.push(wire_item("assistant", "m2", 2, &["answer"]));
            let assistant_request = active_cc_req("temporal", "cfg0", with_assistant.clone());
            transform(
                &s,
                &assistant_request,
                &pctx("git:proj", "/nonexistent-docs", 10_000),
            )
            .unwrap();

            let mut complete = with_assistant;
            complete.push(wire_item("user", "m3", 3, &["question"]));
            let mut active = active_cc_req("temporal", "cfg0", complete.clone());
            active.prev_response_completed_at_ms = Some(10_000);
            // Ingress-time basis: the module clock runs 2h LATER than the proxy's
            // ingress observation (queue plus blocking-arm delay). A now-basis
            // implementation would render +2h here instead of +12m.
            active.request_observed_at_ms = Some(730_000);
            let first = transform(
                &s,
                &active,
                &pctx("git:proj", "/nonexistent-docs", 7_930_000),
            )
            .unwrap();
            assert_eq!(tail_bytes(&first, "m3"), "§3§ <!-- +12m -->\nquestion");
            active.prev_response_completed_at_ms = Some(800_000);
            let replay = transform(
                &s,
                &active,
                &pctx("git:proj", "/nonexistent-docs", 8_000_000),
            )
            .unwrap();
            assert_eq!(tail_bytes(&replay, "m3"), tail_bytes(&first, "m3"));

            let dormant = cc_req("temporal", "cfg0", complete);
            let false_window = transform(
                &s,
                &dormant,
                &pctx("git:proj", "/nonexistent-docs", 1_000_000),
            )
            .unwrap();
            assert_eq!(tail_bytes(&false_window, "m3"), "question");

            let mut temporal_disabled = pctx("git:proj", "/nonexistent-docs", 7_930_000);
            temporal_disabled.temporal_awareness = false;
            let mut disabled_request = active;
            disabled_request.prev_response_completed_at_ms = Some(10_000);
            disabled_request.request_observed_at_ms = Some(730_000);
            let disabled = transform(&s, &disabled_request, &temporal_disabled).unwrap();
            assert_eq!(tail_bytes(&disabled, "m3"), "question");
        });
    }

