    #[test]
    fn prompt_surface_preset_flip_takes_one_hard_then_freezes_defer_bytes() {
        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        let messages = vec![wire_item("user", "m1", 1, &["stable bytes"])];
        let mut full = cc_req("prompt-preset-c6", "cfg", messages);
        full.system_prompt_hash = "same-guidance-hash".to_string();
        let baseline = run(&store, &full, &spine());
        let steady = run(&store, &full, &spine());
        assert_ne!(steady.action, "HARD");

        let mut light = full.clone();
        light.prompt_surface_preset = PromptSurfacePreset::Light;
        let transition = run(&store, &light, &spine());
        assert_eq!(transition.action, "HARD");
        let transition_bytes = serde_json::to_vec(transition.messages()).unwrap();
        assert_eq!(
            transition_bytes,
            serde_json::to_vec(baseline.messages()).unwrap()
        );

        let mut hard_count = 1;
        for _ in 0..5 {
            let defer = run(&store, &light, &spine());
            hard_count += usize::from(defer.action == "HARD");
            assert_eq!(
                serde_json::to_vec(defer.messages()).unwrap(),
                transition_bytes
            );
        }
        assert_eq!(
            hard_count, 1,
            "one preset epoch may create only one HARD fold"
        );
    }

    #[test]
    fn guidance_and_manifest_changes_share_one_prompt_surface_fold() {
        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        let messages = vec![wire_item("user", "m1", 1, &["stable bytes"])];
        let mut full = cc_req("prompt-unified-r5", "cfg", messages);
        full.system_prompt_hash = "guidance-full".to_string();
        run(&store, &full, &spine());
        run(&store, &full, &spine());

        let mut changed = full.clone();
        changed.system_prompt_hash = "guidance-light".to_string();
        changed.prompt_surface_preset = PromptSurfacePreset::Light;
        changed.prompt_surface_tool_descriptions.insert(
            "ctx_search".to_string(),
            "Search override for the new model epoch.".to_string(),
        );
        let full_selection = prompt_surface_selection(&full);
        let changed_selection = prompt_surface_selection(&changed);
        assert_ne!(
            crate::prompt_surface::guidance_content_hash(
                crate::prompt_surface::GUIDANCE_FULL_PRIMARY,
                full_selection.preset,
            ),
            crate::prompt_surface::guidance_content_hash(
                crate::prompt_surface::GUIDANCE_FULL_PRIMARY,
                changed_selection.preset,
            )
        );
        assert_ne!(
            crate::prompt_surface::manifest_content_epoch(&full_selection),
            crate::prompt_surface::manifest_content_epoch(&changed_selection)
        );

        let first = run(&store, &changed, &spine());
        assert_eq!(first.action, "HARD");
        let folded = &store
            .load("prompt-unified-r5")
            .unwrap()
            .meta
            .last_render_config;
        assert_eq!(folded.matches("pse:").count(), 1);
        assert!(!folded.contains("system:"));
        assert!(!folded.contains("manifest:"));
        assert!(!folded.contains("guidance:"));

        let replay = run(&store, &changed, &spine());
        assert_ne!(replay.action, "HARD");
        assert_eq!(
            serde_json::to_vec(first.messages()).unwrap(),
            serde_json::to_vec(replay.messages()).unwrap()
        );
    }

    #[test]
    fn cc_profile_epoch_bump_takes_exactly_one_hard_when_client_config_frozen() {
        let dir = tempfile::tempdir().unwrap();
        let s = store(dir.path());
        let r1 = "pe1/tf1/gfull";
        let messages = vec![wire_item("user", "m1", 1, &["stable bytes"])];
        let request = active_cc_req("staged-tfe", r1, messages);

        run(&s, &request, &spine());
        run(&s, &request, &spine());
        let mut loaded = s.load("staged-tfe").unwrap();
        loaded.meta.last_render_config = effective_render_config_with_epochs(
            &s,
            r1,
            format!("mre{}", crate::MEMORY_RENDER_FORMAT_EPOCH),
            format!("cre{}", crate::COMPARTMENT_RENDER_FORMAT_EPOCH),
            "mpe2".to_string(),
            "tfe3".to_string(),
        );
        s.commit("staged-tfe", loaded.row_version, &loaded.core, &loaded.meta)
            .unwrap();

        // The consumer base string stays frozen while the module epoch moves. Epoch pins
        // are status assertions, not extra wire tokens; changing both identities would
        // coordinate two folds instead of the one fold owned by the module upgrade.
        let pass_a = run(&s, &request, &spine());
        assert_eq!(pass_a.action, "HARD");
        let expected_profile_epoch_3 = effective_render_config_with_epochs(
            &s,
            r1,
            format!("mre{}", crate::MEMORY_RENDER_FORMAT_EPOCH),
            format!("cre{}", crate::COMPARTMENT_RENDER_FORMAT_EPOCH),
            "mpe3".to_string(),
            "tfe3".to_string(),
        );
        assert_eq!(
            s.load("staged-tfe").unwrap().meta.last_render_config,
            expected_profile_epoch_3
        );

        let pass_b = run(&s, &request, &spine());
        assert_eq!(pass_b.action, "SOFT+");
        assert_eq!(
            serde_json::to_vec(pass_a.messages()).unwrap(),
            serde_json::to_vec(pass_b.messages()).unwrap()
        );

        let r2_request = active_cc_req("staged-tfe", "pe1/tf2/gfull", request.messages.clone());
        let pass_c = run(&s, &r2_request, &spine());
        assert_eq!(
            pass_c.action, "HARD",
            "the opaque client base is independently identity-bearing"
        );
    }

    #[test]
    fn opencode_identity_refuses_collateral_cc_profile_epoch_hard() {
        let dir = tempfile::tempdir().unwrap();
        let s = store(dir.path());
        let request = active_opencode_req(
            "opencode-profile-epoch",
            "rust-mode/tf1/gfull",
            vec![wire_item("user", "m1", 1, &["stable bytes"])],
        );
        run(&s, &request, &spine());
        let mut loaded = s.load(&request.session_id).unwrap();
        // Pin the previous format epochs to verify compatibility independently of this binary:
        // memory 2, compartments 2, no OpenCode profile epoch, shared tagger 3.
        let master_identity = effective_render_config_with_epochs(
            &s,
            &request.render_config,
            "mre2".to_string(),
            "cre2".to_string(),
            String::new(),
            "tfe3".to_string(),
        );
        assert_eq!(
            loaded.meta.last_render_config.as_bytes(),
            master_identity.as_bytes(),
            "a Claude Code-only byte change must not alter OpenCode's render identity"
        );
        loaded.meta.last_render_config = master_identity;
        s.commit(
            &request.session_id,
            loaded.row_version,
            &loaded.core,
            &loaded.meta,
        )
        .unwrap();
        let replay = run(&s, &request, &spine());
        assert_eq!(
            replay.action, "SOFT+",
            "OpenCode must not pay a collateral HARD"
        );
    }

