    #[test]
    fn serialized_output_cache_deep_charge_counts_message_metadata_and_none_rows() {
        use std::mem::size_of;

        fn manual_value_retained_bytes(value: &Value) -> usize {
            fn heap(value: &Value) -> usize {
                match value {
                    Value::Null | Value::Bool(_) | Value::Number(_) => 0,
                    Value::String(value) => value.capacity(),
                    Value::Array(values) => values
                        .capacity()
                        .saturating_mul(size_of::<Value>())
                        .saturating_add(values.iter().map(heap).sum::<usize>()),
                    Value::Object(values) => values
                        .len()
                        .saturating_mul(
                            size_of::<String>() + size_of::<Value>() + size_of::<usize>() * 3,
                        )
                        .saturating_add(
                            values
                                .iter()
                                .map(|(key, value)| key.capacity().saturating_add(heap(value)))
                                .sum::<usize>(),
                        ),
                }
            }
            size_of::<Value>().saturating_add(heap(value))
        }

        let input = Value::Object(
            (0..64)
                .map(|index| {
                    (
                        format!("k{index}"),
                        serde_json::json!({"value": format!("v{index}"), "n": index}),
                    )
                })
                .collect(),
        );
        let constructed = CkWireMessage::from_parts(
            "assistant",
            vec![CkWireBlock::bare(ck_wire::CkKind::ToolCall {
                id: "call-output-heavy".to_string(),
                name: "fixture_tool".to_string(),
                input,
                provider_executed: false,
            })],
            None,
            ck_wire::ProviderExtras::new(),
            ck_wire::HarnessMeta {
                harness_id: Some("output-heavy".to_string()),
                ..Default::default()
            },
        );
        let message: CkWireMessage =
            serde_json::from_value(serde_json::to_value(constructed).unwrap()).unwrap();
        let served = ServedMessage::from_message(message);
        let block = &served.message.content[0];
        let block_json = serde_json::to_value(block).unwrap();
        let message_json = serde_json::to_value(served.message.as_ref()).unwrap();
        let ck_wire::CkKind::ToolCall {
            id, name, input, ..
        } = &block.kind
        else {
            panic!("fixture must retain a tool call");
        };
        let block_extra = id
            .capacity()
            .saturating_add(name.capacity())
            .saturating_add(manual_value_retained_bytes(input).saturating_sub(size_of::<Value>()))
            .saturating_add(manual_value_retained_bytes(&block_json));
        let message_retained = size_of::<CkWireMessage>()
            .saturating_add(served.message.role.capacity())
            .saturating_add(
                served
                    .message
                    .content
                    .capacity()
                    .saturating_mul(size_of::<CkWireBlock>()),
            )
            .saturating_add(block_extra)
            .saturating_add(
                served
                    .message
                    .meta
                    .harness_id
                    .as_ref()
                    .map_or(0, String::capacity),
            )
            .saturating_add(manual_value_retained_bytes(&message_json));
        let served_retained = crate::retained_size::ARC_ALLOCATION_OVERHEAD_BYTES
            .saturating_add(message_retained)
            .saturating_add(crate::retained_size::ARC_ALLOCATION_OVERHEAD_BYTES)
            .saturating_add(served.canonical_bytes.len())
            .saturating_add(crate::retained_size::ARC_ALLOCATION_OVERHEAD_BYTES)
            .saturating_add(served.output_identity.len())
            .saturating_add(crate::retained_size::ARC_ALLOCATION_OVERHEAD_BYTES)
            .saturating_add(
                served
                    .block_fingerprints
                    .len()
                    .saturating_mul(size_of::<(String, usize)>()),
            )
            .saturating_add(
                served
                    .block_fingerprints
                    .iter()
                    .map(|(fingerprint, _)| fingerprint.capacity())
                    .sum::<usize>(),
            );
        let mut entries = HashMap::new();
        entries.insert(
            "tail:output-heavy".to_string(),
            SerializedOutputCacheEntry {
                identity: "identity-output-heavy".to_string(),
                served: Some(served.clone()),
            },
        );
        let without_none =
            SerializedOutputCache::entries_retained_bytes("fixture-session", &entries);
        entries.insert(
            "tail:metadata-only".to_string(),
            SerializedOutputCacheEntry {
                identity: "identity-metadata-only".to_string(),
                served: None,
            },
        );
        let buckets = entries.capacity().saturating_mul(8).saturating_add(6) / 7;
        let map_allocation = buckets
            .saturating_mul(size_of::<String>() + size_of::<SerializedOutputCacheEntry>() + 1);
        let expected = map_allocation
            .saturating_add(
                entries
                    .iter()
                    .map(|(key, entry)| {
                        key.capacity()
                            .saturating_add(entry.identity.capacity())
                            .saturating_add(entry.served.as_ref().map_or(0, |_| served_retained))
                    })
                    .sum::<usize>(),
            )
            .saturating_add(size_of::<SerializedOutputSession>())
            .saturating_add(size_of::<usize>() * 3)
            .saturating_add((size_of::<String>() + "fixture-session".len()).saturating_mul(2));
        let retained = SerializedOutputCache::entries_retained_bytes("fixture-session", &entries);
        let legacy = served.canonical_bytes.len();

        assert!(retained >= legacy.saturating_mul(2));
        assert!(
            retained > without_none,
            "served:None row must carry a charge"
        );
        assert!(
            retained.abs_diff(expected) <= expected / 20,
            "serialized-output estimate left 5% fixture tolerance: retained={retained} expected={expected}"
        );
    }

    #[test]
    fn serialized_output_cache_revert_epoch_bump_evicts_session() {
        let (core, meta, request, projection) = output_cache_fixture("m0-v1", "m1-v1");
        let built = build_cached_fixture(&core, &meta, &request, &projection, None, None, true);
        let mut cache = SerializedOutputCache::new(1024 * 1024);
        cache.replace(
            &request.session_id,
            3,
            built.cache_entries,
            built.cache_stats,
        );
        assert!(!cache.snapshot(&request.session_id, 3).entries.is_empty());

        assert!(cache.snapshot(&request.session_id, 4).entries.is_empty());
        assert_eq!(
            cache.stats(&request.session_id),
            SerializedOutputCacheStats::default()
        );
    }

    fn seed_fake_compaction_prior(store: &McStore, key: &str) {
        let messages = (1..=10)
            .map(|ordinal| {
                item(
                    &format!("prior-{ordinal}"),
                    ordinal,
                    &format!("turn {ordinal}"),
                )
            })
            .collect::<Vec<_>>();
        run(store, &req(key, "prior-cfg", messages), &spine());
        store
            .append_compartments(
                key,
                &[
                    comp(1, 1, 3, "prior-3", "history one through three"),
                    comp(2, 4, 6, "prior-6", "history four through six"),
                ],
            )
            .unwrap();
        assert_eq!(store.load(key).unwrap().meta.newest_live_ordinal, 10);
    }

    fn fake_compaction_messages(date: &str, summary: &str) -> Vec<CkIngressMessage> {
        vec![
            wire_item(
                "user",
                "summary",
                1,
                &[
                    &format!("<system-reminder>Today's date: {date}</system-reminder>"),
                    summary,
                ],
            ),
            wire_item("assistant", "tail", 2, &["continued answer"]),
        ]
    }

    fn fake_compaction_request(
        target: &str,
        prior: &str,
        epoch: u64,
        edge_id: u64,
        observed: bool,
        messages: Vec<CkIngressMessage>,
    ) -> TransformRequest {
        let mut request = req(target, "descent-cfg", messages);
        request.lineage_switched = true;
        request.descent_edge_id = edge_id;
        request.prior_conversation_key = prior.to_string();
        request.prior_epoch = 1;
        request.new_epoch = epoch;
        request.constituents = vec![(prior.to_string(), target.to_string(), epoch)];
        request.compaction_observed = observed;
        request
    }

    fn continuation_summary(label: &str) -> String {
        format!(
            "{CONTINUATION_SUMMARY_PREFIX}.\n\nSummary:\nDurable summary {label}\n\nFull transcript: /tmp/session.jsonl"
        )
    }

    #[test]
    fn fake_compaction_descends_materializes_and_write_free_replay_acks() {
        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        seed_fake_compaction_prior(&store, "A");
        let summary = continuation_summary("alpha");
        let request = fake_compaction_request(
            "B",
            "A",
            2,
            101,
            true,
            fake_compaction_messages("2026-08-06", &summary),
        );
        let prior_epoch = store.load("A").unwrap().meta.revert_epoch;

        let first = run(&store, &request, &spine());
        assert_eq!(first.action, "HARD");
        assert_eq!(first.lineage_switch_consumed_id, Some(101));
        // The disposition rides beside the ack so the sender can tell
        // inheritance from a terminal refusal without reading our store
        // (drive round-1: consumed_id alone acked a cycle_detected refusal
        // and read as success from the proxy seat).
        assert_eq!(
            first.lineage_descent_disposition.as_deref(),
            Some("descended")
        );
        assert_eq!(first.ordinal_continuation_base, Some(10));
        assert_eq!(first.coverage_ordinal, Some(11));
        assert!(!first.reconcile_pending);
        assert_eq!(first.messages().len(), 4);
        assert!(first.messages()[0].meta.synthetic && first.messages()[1].meta.synthetic);
        assert!(!first.messages()[2].meta.synthetic);
        assert_eq!(first.messages()[2].role, "user");
        assert_eq!(first.messages()[3].role, "assistant");
        assert!(first
            .messages()
            .iter()
            .all(|message| message.role != "system"));
        assert_eq!(
            first.messages()[2].content[1].kind,
            ck_wire::CkKind::Text {
                text: summary.clone()
            }
        );
        let target = store.load("B").unwrap();
        assert!(target.meta.descent_completed);
        assert!(target.meta.lineage_descent_materialized);
        assert_eq!(target.meta.coverage_ordinal, Some(11));
        assert_eq!(
            store
                .load_compartments("B")
                .unwrap()
                .iter()
                .map(|row| (row.start_message, row.end_message))
                .collect::<Vec<_>>(),
            vec![(1, 3), (4, 6), (11, 11)]
        );
        assert_eq!(store.load("A").unwrap().meta.revert_epoch, prior_epoch + 1);

        let second = run(&store, &request, &spine());
        assert_eq!(second.action, "SOFT+");
        assert_eq!(second.lineage_switch_consumed_id, Some(101));
        // The write-free replay arm also names its outcome.
        assert_eq!(
            second.lineage_descent_disposition.as_deref(),
            Some("replay")
        );
        assert!(!second.committed, "durable replay must stay write-free");
        assert_eq!(store.load("A").unwrap().meta.revert_epoch, prior_epoch + 1);
    }

    #[test]
    fn fake_compaction_anchor_fail_closes_but_sibling_date_and_overlays_are_exempt() {
        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        seed_fake_compaction_prior(&store, "A");
        let summary = continuation_summary("stable");
        let request = fake_compaction_request(
            "B",
            "A",
            2,
            201,
            true,
            fake_compaction_messages("2026-08-06", &summary),
        );
        run(&store, &request, &spine());

        let mut edited = request.clone();
        edited.render_config = "anchor-edited".to_string();
        edited.messages[0].ck.content[1].kind = ck_wire::CkKind::Text {
            text: continuation_summary("EDITED"),
        };
        edited.messages[0].ck.content[1].mark_modified();
        let edited_response = run(&store, &edited, &spine());
        assert_eq!(edited_response.action, "SOFT+");
        assert!(edited_response.reconcile_pending);
        assert_eq!(edited_response.coverage_ordinal, Some(11));
        assert_eq!(
            edited_response.messages().len(),
            4,
            "anchor edit cannot trim the tail"
        );

        let mut deleted = request.clone();
        deleted.render_config = "anchor-deleted".to_string();
        deleted.messages.remove(0);
        deleted.messages[0].ordinal = 1;
        deleted.messages[0].ck.meta.ordinal = Some(1);
        let deleted_response = run(&store, &deleted, &spine());
        assert_eq!(deleted_response.action, "SOFT+");
        assert!(deleted_response.reconcile_pending);
        assert_eq!(
            deleted_response.messages().len(),
            3,
            "deleted anchor stays no-trim"
        );

        let mut rollover = request.clone();
        rollover.render_config = "date-rollover".to_string();
        rollover.messages = fake_compaction_messages("2026-08-07", &summary);
        let rollover_response = run(&store, &rollover, &spine());
        assert_eq!(rollover_response.action, "HARD");
        assert!(!rollover_response.reconcile_pending);
        assert_eq!(
            rollover_response.messages()[2].content[1].kind,
            request.messages[0].ck.content[1].kind
        );

        let mut active_surface = rollover.clone();
        active_surface.render_config = "active-overlays-and-strips".to_string();
        active_surface.serializer_profile = "claude-code-anthropic".to_string();
        active_surface.tool_present = true;
        active_surface.clear_reasoning_age = 1;
        active_surface.protected_tags = 0;
        let active_response = run(&store, &active_surface, &spine());
        assert_eq!(active_response.action, "HARD");
        assert!(!active_response.reconcile_pending);
        assert_eq!(
            active_response.messages()[2].content,
            active_surface.messages[0].ck.content,
            "the anchor message is exempt from both overlays and production strips"
        );
    }

    #[test]
    fn fake_compaction_recognition_and_terminal_protocol_branches_are_narrow() {
        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        seed_fake_compaction_prior(&store, "A");
        let summary = continuation_summary("shape");

        let missing_flag = fake_compaction_request(
            "flag-missing",
            "A",
            2,
            301,
            false,
            fake_compaction_messages("2026-08-06", &summary),
        );
        let missing_flag_response = run(&store, &missing_flag, &spine());
        assert_eq!(missing_flag_response.lineage_switch_consumed_id, Some(301));
        assert_eq!(
            store
                .load("flag-missing")
                .unwrap()
                .meta
                .lineage_descent_disposition,
            "observed_flag_missing_shape_present"
        );
        assert!(store.load_compartments("flag-missing").unwrap().is_empty());

        let rewind = fake_compaction_request(
            "rewind",
            "A",
            2,
            302,
            true,
            vec![item("rewound-user", 1, "ordinary restored history")],
        );
        let rewind_response = run(&store, &rewind, &spine());
        assert_eq!(rewind_response.lineage_switch_consumed_id, Some(302));
        assert_eq!(
            store
                .load("rewind")
                .unwrap()
                .meta
                .lineage_descent_disposition,
            "not_compaction_shape"
        );
        assert!(store.load_compartments("rewind").unwrap().is_empty());

        let mut wrong_position_messages = fake_compaction_messages("2026-08-06", &summary);
        wrong_position_messages[0].ck.content.swap(0, 1);
        let wrong_position =
            fake_compaction_request("wrong-position", "A", 2, 303, true, wrong_position_messages);
        run(&store, &wrong_position, &spine());
        assert_eq!(
            store
                .load("wrong-position")
                .unwrap()
                .meta
                .lineage_descent_disposition,
            "not_compaction_shape",
            "recognition must use the last text block, never content[0] or concatenation"
        );

        let mut subagent = fake_compaction_request(
            "subagent-target",
            "A",
            2,
            304,
            true,
            fake_compaction_messages("2026-08-06", &summary),
        );
        subagent.is_subagent = true;
        let subagent_response = run(&store, &subagent, &spine());
        assert_eq!(subagent_response.action, "PASSTHROUGH");
        assert_eq!(subagent_response.lineage_switch_consumed_id, None);
        assert!(store
            .load("subagent-target")
            .unwrap()
            .meta
            .lineage_descent_disposition
            .is_empty());
        assert_eq!(subagent_response.messages().len(), subagent.messages.len());

        let mut mismatch = fake_compaction_request(
            "resolved-target",
            "A",
            2,
            305,
            true,
            fake_compaction_messages("2026-08-06", &summary),
        );
        mismatch.constituents[0].1 = "other-target".to_string();
        let mismatch_response = run(&store, &mismatch, &spine());
        assert_eq!(mismatch_response.action, "PASSTHROUGH");
        assert_eq!(mismatch_response.lineage_switch_consumed_id, None);
        assert!(store.load("resolved-target").unwrap().row_version.is_none());
    }

    #[test]
    fn continued_lineage_survives_post_descent_folds_advancing_past_the_seam() {
        // Prod wedge f6a4ca71 (2026-08-11): the continuation base is frozen at
        // the descent seam, but the successor's historian keeps folding. The
        // old equality check fenced every pass after the first successor fold
        // (+2 / +5 compartment-end overhangs); coverage PAST the seam must be
        // accepted, coverage SHORT of it must still refuse.
        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        seed_fake_compaction_prior(&store, "A");
        let summary = continuation_summary("seam");
        let descent = fake_compaction_request(
            "B",
            "A",
            2,
            501,
            true,
            fake_compaction_messages("2026-08-06", &summary),
        );
        let first = run(&store, &descent, &spine());
        assert_eq!(
            first.lineage_descent_disposition.as_deref(),
            Some("descended")
        );
        assert_eq!(first.ordinal_continuation_base, Some(10));

        // The successor runs on: the historian folds messages past the seam,
        // exactly what a healthy long-lived successor does.
        store
            .append_compartments("B", &[comp(4, 12, 14, "successor-14", "successor work")])
            .unwrap();

        // An ordinary follow-up pass (no lineage switch) must NOT fence on the
        // advanced compartment end.
        // The successor's wire continues the predecessor's numbering: first
        // live ordinal is base + 1, exactly as the gateway's edge counter
        // assigns it.
        let mut follow_up_messages = vec![
            wire_item(
                "user",
                "summary",
                11,
                &[
                    "<system-reminder>Today's date: 2026-08-06</system-reminder>",
                    &summary,
                ],
            ),
            wire_item("assistant", "tail", 12, &["continued answer"]),
        ];
        follow_up_messages.push(item("succ-13", 13, "successor turn thirteen"));
        follow_up_messages.push(item("succ-14", 14, "successor turn fourteen"));
        let follow_up = req("B", "descent-cfg", follow_up_messages);
        let outcome = transform(
            &store,
            &follow_up,
            &pctx("git:proj", "/nonexistent-docs", 0),
        );
        assert!(
            outcome.is_ok(),
            "post-descent fold past the seam must not fence: {:?}",
            outcome.err()
        );
    }

    #[test]
    fn continued_lineage_stable_defer_rejects_mutated_anchor_after_post_seam_fold() {
        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        seed_fake_compaction_prior(&store, "A");
        let summary = continuation_summary("stable-seam");
        let descent = fake_compaction_request(
            "B",
            "A",
            2,
            502,
            true,
            fake_compaction_messages("2026-08-06", &summary),
        );
        run(&store, &descent, &spine());
        store
            .append_compartments("B", &[comp(4, 12, 14, "successor-14", "successor work")])
            .unwrap();

        let follow_up_messages = vec![
            wire_item(
                "user",
                "summary",
                11,
                &[
                    "<system-reminder>Today's date: 2026-08-06</system-reminder>",
                    &summary,
                ],
            ),
            wire_item("assistant", "tail", 12, &["continued answer"]),
            item("succ-13", 13, "successor turn thirteen"),
            item("succ-14", 14, "successor turn fourteen"),
        ];
        let follow_up = req("B", "descent-cfg", follow_up_messages);
        let intact = run(&store, &follow_up, &spine());
        assert_eq!(intact.action, "SOFT+");
        assert!(!intact.reconcile_pending);

        let mut mutated = follow_up.clone();
        mutated.messages[0].ck.content[1].kind = ck_wire::CkKind::Text {
            text: continuation_summary("MUTATED"),
        };
        mutated.messages[0].ck.content[1].mark_modified();
        let refused = run(&store, &mutated, &spine());
        assert_eq!(refused.action, "SOFT+");
        assert!(refused.reconcile_pending);
        assert_eq!(
            refused.materialize_reason.as_deref(),
            Some("lineage_anchor_mismatch")
        );
        assert_eq!(
            refused
                .messages()
                .iter()
                .filter(|message| !message.meta.synthetic)
                .count(),
            mutated.messages.len(),
            "a mutated continuation anchor must fail closed without trimming live input"
        );
    }

    #[test]
    fn continued_lineage_tolerates_a_synthetic_head_like_the_seam_check() {
        // The seam check finds the boundary at the first non-synthetic message;
        // the anchor check must use the same rule or a synthetic-marked head
        // (normalized synthetic todo) passes one gate and defers forever on the
        // other.
        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        seed_fake_compaction_prior(&store, "A");
        let summary = continuation_summary("synthetic-head");
        let descent = fake_compaction_request(
            "B",
            "A",
            2,
            601,
            true,
            fake_compaction_messages("2026-08-06", &summary),
        );
        let first = run(&store, &descent, &spine());
        assert_eq!(
            first.lineage_descent_disposition.as_deref(),
            Some("descended")
        );

        // Follow-up pass whose head message is synthetic-marked; the anchor
        // stays the first NON-synthetic message.
        let mut synthetic_head = item("synth-head", 10, "synthetic filler");
        synthetic_head.ck.meta.synthetic = true;
        let mut follow_up_messages = vec![
            synthetic_head,
            wire_item(
                "user",
                "summary",
                11,
                &[
                    "<system-reminder>Today's date: 2026-08-06</system-reminder>",
                    &summary,
                ],
            ),
            wire_item("assistant", "tail", 12, &["continued answer"]),
        ];
        follow_up_messages.push(item("succ-13", 13, "successor turn thirteen"));
        let follow_up = req("B", "descent-cfg", follow_up_messages);
        let outcome = transform(
            &store,
            &follow_up,
            &pctx("git:proj", "/nonexistent-docs", 0),
        );
        assert!(
            outcome.is_ok(),
            "synthetic head must not fail the anchor gate: {:?}",
            outcome.err()
        );
        let response = outcome.unwrap();
        assert!(
            !response.reconcile_pending,
            "synthetic head must not latch a lineage_anchor_mismatch defer"
        );
    }

    #[test]
    fn continued_lineage_missing_boundary_aborts_instead_of_rebasing_to_one() {
        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        seed_fake_compaction_prior(&store, "A");
        let request = fake_compaction_request(
            "B",
            "A",
            2,
            401,
            true,
            fake_compaction_messages("2026-08-06", &continuation_summary("fallback")),
        );
        run(&store, &request, &spine());
        store
            .replace_compartments(
                "B",
                &[
                    comp(1, 1, 3, "prior-3", "history one through three"),
                    comp(2, 4, 6, "prior-6", "history four through six"),
                ],
            )
            .unwrap();
        let error =
            transform(&store, &request, &pctx("git:proj", "/nonexistent-docs", 0)).unwrap_err();
        assert!(matches!(error, TransformError::LineageProtocol(_)));
        assert!(error
            .to_string()
            .contains("refusing silent re-base-to-1 fallback"));
    }

    #[test]
    fn channel2_directive_id_hashes_session_and_arming_watermark_deterministically() {
        assert_eq!(
            channel2_directive_id("ses", 1),
            "f585181359b732157103a0bd050a378a89c47585fcd12f5b90e13ec864aa70d8"
        );
        assert_ne!(
            channel2_directive_id("ses", 1),
            channel2_directive_id("ses", 2)
        );
        assert_ne!(
            channel2_directive_id("ses", 1),
            channel2_directive_id("other", 1)
        );
    }
